import Foundation

let dkxStringsTable: [String: [String: String]] = {
    guard let data = dkxStringsJSON.data(using: .utf8), let table = try? JSONSerialization.jsonObject(with: data) as? [String: [String: String]] else {
        return [:]
    }
    return table
}()

