 "iOS при каждой смене значка показывает окно, что значок изменён.\n\nВ Telegram свой выбор значка в «Оформлении» остался как был. Новые картинки добавляются в сборку, с телефона их не поставить.": {
  "ar": "يعرض iOS عند كل تغيير للأيقونة نافذة تفيد بأنها تغيّرت.\n\nاختيار الأيقونة الخاص بـ Telegram في «المظهر» بقي كما هو. تُضاف الصور الجديدة عند بناء التطبيق، ولا يمكن تثبيتها من الهاتف.",
  "be": "iOS пры кожнай змене значка паказвае акно, што значок зменены.\n\nУ Telegram уласны выбар значка ў «Афармленні» застаўся як быў. Новыя карцінкі дадаюцца ў зборку, з тэлефона іх не паставіць.",
  "ca": "iOS mostra un avís cada vegada que canvia la icona.\n\nEl selector d'icona propi de Telegram a «Aparença» es queda com estava. Les imatges noves s'afegeixen a la compilació, no es poden instal·lar des del telèfon.",
  "de": "iOS zeigt bei jedem Wechsel des Icons einen Hinweis, dass das Icon geändert wurde.\n\nDie eigene Icon-Auswahl von Telegram unter „Darstellung“ bleibt wie bisher. Neue Bilder kommen mit dem Build dazu, vom Telefon aus lassen sie sich nicht installieren.",
  "en": "iOS shows an alert every time the icon changes.\n\nTelegram's own icon picker in “Appearance” stays as it was. New images are added in the build, they can't be installed from the phone.",
  "es": "iOS muestra un aviso cada vez que cambia el icono.\n\nEl selector de icono propio de Telegram en «Apariencia» sigue como estaba. Las imágenes nuevas se añaden en la compilación, no se pueden instalar desde el teléfono.",
  "fa": "iOS با هر تغییر آیکون، پنجره‌ای نشان می‌دهد که آیکون تغییر کرد.\n\nانتخاب آیکون خود Telegram در «ظاهر» مثل قبل مانده است. تصویرهای جدید هنگام ساخت برنامه اضافه می‌شوند و از روی گوشی نصب نمی‌شوند.",
  "fr": "iOS affiche une alerte à chaque changement d'icône pour signaler que l'icône a changé.\n\nLe choix d'icône propre à Telegram dans « Apparence » reste tel quel. Les nouvelles images sont ajoutées dans la version de l'app, on ne peut pas les installer depuis le téléphone.",
  "id": "iOS menampilkan pemberitahuan setiap kali ikon diganti.\n\nPilihan ikon bawaan Telegram di “Tampilan” tetap seperti semula. Gambar baru ditambahkan saat build aplikasi, tidak bisa dipasang dari ponsel.",
  "it": "iOS mostra un avviso ogni volta che l'icona cambia.\n\nIl selettore di icone di Telegram in «Aspetto» resta com'era. Le nuove immagini si aggiungono nella build, non si possono installare dal telefono.",
  "ko": "iOS는 아이콘을 바꿀 때마다 아이콘이 변경되었다는 창을 표시합니다.\n\nTelegram 자체의 ‘외관’ 아이콘 선택은 그대로입니다. 새 이미지는 앱을 빌드할 때 추가되며 휴대폰에서 설치할 수 없습니다.",
  "ms": "iOS memaparkan makluman setiap kali ikon ditukar.\n\nPilihan ikon Telegram sendiri dalam “Penampilan” kekal seperti dahulu. Gambar baharu ditambah semasa binaan aplikasi, ia tidak boleh dipasang dari telefon.",
  "nl": "iOS toont bij elke wijziging van het icoon een melding dat het icoon is gewijzigd.\n\nDe eigen icoonkeuze van Telegram in “Weergave” blijft zoals hij was. Nieuwe afbeeldingen worden in de build toegevoegd, vanaf de telefoon kun je ze niet instellen.",
  "pl": "Przy każdej zmianie ikony iOS pokazuje okno, że ikona została zmieniona.\n\nWbudowany wybór ikony Telegram w sekcji „Wygląd” pozostał bez zmian. Nowe obrazki dodaje się w kompilacji, nie da się ich ustawić z telefonu.",
  "pt": "O iOS mostra um aviso sempre que o ícone muda.\n\nNo Telegram, a escolha de ícone própria em “Aparência” continua como estava. Novas imagens são adicionadas na compilação do app, não dá para instalá-las pelo celular.",
  "tr": "iOS, simge her değiştiğinde simgenin değiştiğini bildiren bir pencere gösterir.\n\nTelegram'ın kendi simge seçimi “Görünüm” bölümünde olduğu gibi kaldı. Yeni resimler derlemeye eklenir, telefondan yüklenemez.",
  "uk": "iOS під час кожної зміни значка показує вікно, що значок змінено.\n\nУ Telegram власний вибір значка в «Оформленні» лишився як був. Нові картинки додаються у збірку, з телефона їх не встановити.",
  "uz": "Har safar ikonka almashtirilganda iOS ikonka oʻzgargani haqida oyna koʻrsatadi.\n\nTelegramning oʻz ikonka tanlovi “Koʻrinish” boʻlimida avvalgidek qoldi. Yangi rasmlar ilova yigʻmasiga qoʻshiladi, ularni telefondan oʻrnatib boʻlmaydi."
 },
