 "«{}» снимется со всех сообщений.": {
  "ar": "سيُزال الوسم «{}» من جميع الرسائل.",
  "be": "«{}» будзе знята з усіх паведамленняў.",
  "ca": "«{}» es traurà de tots els missatges.",
  "de": "„{}“ wird von allen Nachrichten entfernt.",
  "en": "“{}” will be removed from all messages.",
  "es": "«{}» se quitará de todos los mensajes.",
  "fa": "برچسب «{}» از همه پیام‌ها برداشته می‌شود.",
  "fr": "L'étiquette « {} » sera retirée de tous les messages.",
  "id": "“{}” akan dilepas dari semua pesan.",
  "it": "«{}» verrà rimossa da tutti i messaggi.",
  "ko": "‘{}’ 라벨이 모든 메시지에서 제거됩니다.",
  "ms": "“{}” akan dibuang daripada semua mesej.",
  "nl": "“{}” wordt van alle berichten verwijderd.",
  "pl": "Etykieta „{}” zostanie zdjęta ze wszystkich wiadomości.",
  "pt": "“{}” será removida de todas as mensagens.",
  "tr": "“{}” tüm mesajlardan kaldırılacak.",
  "uk": "«{}» буде знято з усіх повідомлень.",
  "uz": "“{}” barcha xabarlardan olib tashlanadi."
 },
 "«{}» снимется со всех чатов.": {
  "ar": "سيُزال الوسم «{}» من جميع المحادثات.",
  "be": "«{}» будзе знята з усіх чатаў.",
  "ca": "«{}» es traurà de tots els xats.",
  "de": "„{}“ wird von allen Chats entfernt.",
  "en": "“{}” will be removed from all chats.",
  "es": "«{}» se quitará de todos los chats.",
  "fa": "برچسب «{}» از همه گفتگوها برداشته می‌شود.",
  "fr": "L'étiquette « {} » sera retirée de toutes les discussions.",
  "id": "“{}” akan dilepas dari semua obrolan.",
  "it": "«{}» verrà rimossa da tutte le chat.",
  "ko": "‘{}’ 라벨이 모든 대화에서 제거됩니다.",
  "ms": "“{}” akan dibuang daripada semua bual.",
  "nl": "“{}” wordt van alle chats verwijderd.",
  "pl": "Etykieta „{}” zostanie zdjęta ze wszystkich czatów.",
  "pt": "“{}” será removida de todos os chats.",
  "tr": "“{}” tüm sohbetlerden kaldırılacak.",
  "uk": "«{}» буде знято з усіх чатів.",
  "uz": "“{}” barcha chatlardan olib tashlanadi."
 },
