 "В чате шаблоны открываются кнопкой в поле ввода, рядом со стикерами. Выбранный текст вставляется туда, где стоит курсор, и его можно дописать перед отправкой. Порядок в меню тот же, что здесь.": {
  "ar": "في المحادثة، تُفتح القوالب بزر في حقل الإدخال بجانب الملصقات. يُدرج النص المختار في موضع المؤشر، ويمكن إكماله قبل الإرسال. الترتيب في القائمة هو نفسه هنا.",
  "be": "У чаце шаблоны адкрываюцца кнопкай у полі ўводу, побач са стыкерамі. Выбраны тэкст устаўляецца туды, дзе стаіць курсор, і яго можна дапісаць перад адпраўкай. Парадак у меню той жа, што тут.",
  "ca": "En un xat, les plantilles s'obren amb el botó del camp de text, al costat dels adhesius. El text triat s'insereix on hi ha el cursor i el podeu completar abans d'enviar-lo. L'ordre del menú és el mateix que aquí.",
  "de": "Im Chat öffnest du die Vorlagen mit dem Button im Eingabefeld, neben den Stickern. Der gewählte Text wird an der Cursorposition eingefügt und lässt sich vor dem Senden ergänzen. Die Reihenfolge im Menü ist dieselbe wie hier.",
  "en": "In a chat, templates open from the button in the input field, next to stickers. The chosen text is inserted at the cursor and can be edited before sending. The menu order is the same as here.",
  "es": "En un chat, las plantillas se abren con el botón del campo de texto, junto a los stickers. El texto elegido se inserta donde está el cursor y se puede completar antes de enviarlo. El orden del menú es el mismo que aquí.",
  "fa": "در گفتگو، الگوها با دکمه‌ای در فیلد ورودی کنار استیکرها باز می‌شوند. متن انتخاب‌شده در محل مکان‌نما درج می‌شود و می‌توانید پیش از ارسال آن را کامل کنید. ترتیب در منو همان ترتیب اینجاست.",
  "fr": "Dans une discussion, les modèles s'ouvrent avec le bouton du champ de saisie, à côté des stickers. Le texte choisi est inséré à l'emplacement du curseur et peut être complété avant l'envoi. L'ordre dans le menu est le même qu'ici.",
  "id": "Di obrolan, templat dibuka dengan tombol di kolom pesan, di sebelah stiker. Teks yang dipilih disisipkan di posisi kursor dan bisa dilengkapi sebelum dikirim. Urutan di menu sama dengan di sini.",
  "it": "In chat, i modelli si aprono con il pulsante nel campo di testo, accanto agli sticker. Il testo scelto viene inserito dove si trova il cursore e puoi completarlo prima di inviarlo. L'ordine nel menu è lo stesso di qui.",
  "ko": "대화에서 템플릿은 입력창의 스티커 옆 버튼으로 엽니다. 선택한 텍스트는 커서 위치에 삽입되며 보내기 전에 이어서 쓸 수 있습니다. 메뉴 순서는 여기와 같습니다.",
  "ms": "Dalam bual, templat dibuka dengan butang di ruang mesej, di sebelah stiker. Teks yang dipilih disisipkan di kedudukan kursor dan boleh ditambah sebelum dihantar. Susunan dalam menu sama seperti di sini.",
  "nl": "In een chat open je sjablonen met de knop in het invoerveld, naast de stickers. De gekozen tekst wordt ingevoegd waar de cursor staat en je kunt hem aanvullen voor het versturen. De volgorde in het menu is dezelfde als hier.",
  "pl": "W czacie szablony otwiera się przyciskiem w polu wpisywania, obok naklejek. Wybrany tekst wstawia się tam, gdzie jest kursor, i można go uzupełnić przed wysłaniem. Kolejność w menu jest taka sama jak tutaj.",
  "pt": "No chat, os modelos abrem pelo botão no campo de mensagem, ao lado dos stickers. O texto escolhido é inserido onde está o cursor e pode ser completado antes de enviar. A ordem no menu é a mesma daqui.",
  "tr": "Sohbette şablonlar, giriş alanında çıkartmaların yanında bulunan düğmeyle açılır. Seçilen metin imlecin bulunduğu yere eklenir ve göndermeden önce tamamlanabilir. Menüdeki sıra buradakiyle aynıdır.",
  "uk": "У чаті шаблони відкриваються кнопкою в полі введення, поруч зі стікерами. Вибраний текст вставляється туди, де стоїть курсор, і його можна дописати перед надсиланням. Порядок у меню той самий, що тут.",
  "uz": "Chatda shablonlar kiritish maydonidagi, stikerlar yonidagi tugma bilan ochiladi. Tanlangan matn kursor turgan joyga qoʻyiladi, uni yuborishdan oldin toʻldirish mumkin. Menyudagi tartib bu yerdagidek."
 },
