 "Включите Google Drive в настройках Dkx и войдите в Google.": {
  "ar": "فعّل Google Drive في إعدادات Dkx وسجّل الدخول إلى Google.",
  "be": "Уключыце Google Drive у наладах Dkx і ўвайдзіце ў Google.",
  "ca": "Activeu Google Drive a la configuració de Dkx i inicieu la sessió a Google.",
  "de": "Aktiviere Google Drive in den Dkx-Einstellungen und melde dich bei Google an.",
  "en": "Turn on Google Drive in Dkx settings and sign in to Google.",
  "es": "Activa Google Drive en los ajustes de Dkx e inicia sesión en Google.",
  "fa": "Google Drive را در تنظیمات Dkx روشن کنید و وارد Google شوید.",
  "fr": "Activez Google Drive dans les paramètres Dkx et connectez-vous à Google.",
  "id": "Aktifkan Google Drive di pengaturan Dkx dan masuk ke Google.",
  "it": "Attiva Google Drive nelle impostazioni di Dkx e accedi a Google.",
  "ko": "Dkx 설정에서 Google Drive를 켜고 Google에 로그인하세요.",
  "ms": "Hidupkan Google Drive dalam tetapan Dkx dan log masuk ke Google.",
  "nl": "Zet Google Drive aan in de Dkx-instellingen en log in bij Google.",
  "pl": "Włącz Google Drive w ustawieniach Dkx i zaloguj się do Google.",
  "pt": "Ative o Google Drive nas configurações do Dkx e entre no Google.",
  "tr": "Dkx ayarlarında Google Drive'a yüklemeyi açın ve Google hesabına giriş yapın.",
  "uk": "Увімкніть Google Drive у налаштуваннях Dkx і увійдіть у Google.",
  "uz": "Dkx sozlamalarida Google Drivega yuklashni yoqing va Google hisobiga kiring."
 },
 "Включённый тумблер прячет строку. Вкладки «Чаты» и «Настройки» и строка Dkx не прячутся, иначе спрятанное было бы не вернуть. Строки, которых у вас и так нет, например Прокси без настроенного прокси, не появятся и при выключенном тумблере.": {
  "ar": "المفتاح المفعّل يُخفي الصف. لا يمكن إخفاء علامتي التبويب «المحادثات» و«الإعدادات» وصف Dkx، وإلا لما أمكن استعادة ما أُخفي. الصفوف غير الموجودة لديك أصلًا، مثل البروكسي دون بروكسي مُعدّ، لن تظهر حتى مع إيقاف المفتاح.",
  "be": "Уключаны пераключальнік хавае радок. Укладкі «Чаты» і «Налады» і радок Dkx не хаваюцца, інакш схаванае было б не вярнуць. Радкі, якіх у вас і так няма, напрыклад Проксі без наладжанага проксі, не з'явяцца і пры выключаным пераключальніку.",
  "ca": "Un interruptor activat amaga la fila. Les pestanyes «Xats» i «Configuració» i la fila Dkx no s'amaguen, perquè si no, no hi hauria manera de recuperar el que s'ha amagat. Les files que de tota manera no teniu, com ara Servidor intermediari sense cap servidor configurat, no apareixeran encara que l'interruptor estigui desactivat.",
  "de": "Ein eingeschalteter Schalter blendet die Zeile aus. Die Tabs „Chats“ und „Einstellungen“ sowie die Dkx-Zeile lassen sich nicht ausblenden, sonst gäbe es keinen Weg zurück. Zeilen, die du ohnehin nicht hast, etwa Proxy ohne eingerichteten Proxy, erscheinen auch bei ausgeschaltetem Schalter nicht.",
  "en": "A switch that is on hides the row. The “Chats” and “Settings” tabs and the Dkx row can't be hidden, otherwise there would be no way back. Rows you don't have anyway, such as Proxy without a configured proxy, won't appear even with the switch off.",
  "es": "Un interruptor activado oculta la fila. Las pestañas «Chats» y «Ajustes» y la fila Dkx no se ocultan, porque si no, no habría forma de recuperar lo oculto. Las filas que de todos modos no tienes, como Proxy sin un proxy configurado, no aparecerán aunque el interruptor esté desactivado.",
  "fa": "کلید روشن، ردیف را پنهان می‌کند. زبانه‌های «گفتگوها» و «تنظیمات» و ردیف Dkx پنهان نمی‌شوند، وگرنه راهی برای برگرداندن موارد پنهان نمی‌ماند. ردیف‌هایی که به‌هرحال ندارید، مثلاً پروکسی بدون پروکسی تنظیم‌شده، با کلید خاموش هم ظاهر نمی‌شوند.",
  "fr": "Un interrupteur activé masque la ligne. Les onglets « Discussions » et « Paramètres » et la ligne Dkx ne peuvent pas être masqués, sinon ce qui est masqué ne pourrait plus être rétabli. Les lignes que vous n'avez pas de toute façon, comme Proxy sans proxy configuré, n'apparaissent pas, même avec l'interrupteur désactivé.",
  "id": "Jika sakelar aktif, baris disembunyikan. Tab “Obrolan” dan “Pengaturan” serta baris Dkx tidak bisa disembunyikan, karena kalau bisa, yang disembunyikan tidak akan bisa dikembalikan. Baris yang memang tidak Anda punya, misalnya Proxy tanpa proxy yang diatur, tidak akan muncul meski sakelar dimatikan.",
  "it": "Un interruttore attivo nasconde la riga. Le schede «Chat» e «Impostazioni» e la riga Dkx non si nascondono, altrimenti non ci sarebbe modo di ripristinare ciò che è nascosto. Le righe che comunque non hai, per esempio Proxy senza un proxy configurato, non compariranno nemmeno con l'interruttore disattivato.",
  "ko": "스위치를 켜면 해당 행이 숨겨집니다. ‘대화’, ‘설정’ 탭과 Dkx 행은 숨길 수 없습니다. 숨기면 되돌릴 방법이 없기 때문입니다. 원래 없는 행, 예를 들어 프록시를 설정하지 않았을 때의 프록시 행은 스위치를 꺼도 나타나지 않습니다.",
  "ms": "Suis yang dihidupkan menyembunyikan baris. Tab “Bual” dan “Tetapan” serta baris Dkx tidak boleh disembunyikan, jika tidak, yang tersembunyi tidak dapat dikembalikan. Baris yang memang tiada pada anda, contohnya Proksi tanpa proksi yang ditetapkan, tidak akan muncul walaupun suis dimatikan.",
  "nl": "Een ingeschakelde schakelaar verbergt de rij. De tabbladen “Chats” en “Instellingen” en de rij Dkx kunnen niet worden verborgen, anders kon je het verborgene niet meer terughalen. Rijen die je toch al niet hebt, zoals Proxy zonder ingestelde proxy, verschijnen ook niet als de schakelaar uit staat.",
  "pl": "Włączony przełącznik ukrywa wiersz. Karty „Czaty” i „Ustawienia” oraz wiersz Dkx się nie ukrywają, inaczej nie dałoby się przywrócić ukrytego. Wiersze, których i tak nie masz, na przykład Proxy bez skonfigurowanego proxy, nie pojawią się także przy wyłączonym przełączniku.",
  "pt": "Com a opção ativada, a linha fica oculta. As abas “Chats” e “Configurações” e a linha Dkx não podem ser ocultadas, senão não haveria como trazer de volta o que foi ocultado. Linhas que você já não tem, como Proxy sem um proxy configurado, não aparecem mesmo com a opção desativada.",
  "tr": "Açık anahtar satırı gizler. “Sohbetler” ve “Ayarlar” sekmeleri ile Dkx satırı gizlenmez, aksi halde gizlenen geri getirilemezdi. Zaten sizde olmayan satırlar, örneğin vekil sunucu ayarlanmamışken Vekil Sunucu, anahtar kapalıyken de görünmez.",
  "uk": "Увімкнений перемикач ховає рядок. Вкладки «Чати» і «Налаштування» та рядок Dkx не ховаються, інакше сховане було б не повернути. Рядки, яких у вас і так немає, наприклад Проксі без налаштованого проксі, не зʼявляться й при вимкненому перемикачі.",
  "uz": "Yoqilgan holatda qator berkitiladi. “Chatlar” va “Sozlamalar” boʻlimlari hamda Dkx qatori berkitilmaydi, aks holda berkitilganini qaytarib boʻlmasdi. Sizda baribir yoʻq qatorlar, masalan, proksi sozlanmagan boʻlsa Proksi, oʻchirilgan holatda ham chiqmaydi."
 },
 "Войдите в свой Google-аккаунт, чтобы выгружать медиа на Google Drive.": {
