 "Все, кто писал последним, уже получили ответ. Порог ожидания настраивается в настройках Dkx.": {
  "ar": "كل من كتب الرسالة الأخيرة تلقى ردًا بالفعل. يُضبط حد الانتظار في إعدادات Dkx.",
  "be": "Усе, хто пісаў апошнім, ужо атрымалі адказ. Парог чакання мяняецца ў наладах Dkx.",
  "ca": "Totes les persones que han escrit l'últim missatge ja tenen resposta. El llindar d'espera es defineix a la configuració de Dkx.",
  "de": "Alle, die zuletzt geschrieben haben, haben schon eine Antwort bekommen. Die Schwelle für die Wartezeit stellst du in den Dkx-Einstellungen ein.",
  "en": "Everyone who wrote last has already got a reply. The waiting threshold is set in Dkx settings.",
  "es": "Todas las personas que escribieron el último mensaje ya tienen respuesta. El umbral de espera se configura en los ajustes de Dkx.",
  "fa": "همه کسانی که آخرین پیام را فرستاده‌اند پاسخ گرفته‌اند. آستانه انتظار در تنظیمات Dkx تنظیم می‌شود.",
  "fr": "Toutes les personnes qui ont écrit en dernier ont déjà reçu une réponse. Le seuil d'attente se règle dans les paramètres Dkx.",
  "id": "Semua yang terakhir menulis sudah dibalas. Batas waktu tunggu diatur di pengaturan Dkx.",
  "it": "Tutte le persone che hanno scritto l'ultimo messaggio hanno già ricevuto risposta. La soglia di attesa si imposta nelle impostazioni di Dkx.",
  "ko": "마지막으로 메시지를 보낸 사람 모두 이미 답장을 받았습니다. 대기 기준은 Dkx 설정에서 바꿀 수 있습니다.",
  "ms": "Semua yang menulis terakhir sudah dibalas. Had masa menunggu ditetapkan dalam tetapan Dkx.",
  "nl": "Iedereen die als laatste schreef, heeft al antwoord gekregen. De wachtdrempel stel je in bij de Dkx-instellingen.",
  "pl": "Wszyscy, którzy napisali ostatni, dostali już odpowiedź. Próg oczekiwania zmienisz w ustawieniach Dkx.",
  "pt": "Todos que escreveram por último já receberam resposta. O limite de espera é definido nas configurações do Dkx.",
  "tr": "Son yazan herkes zaten yanıt aldı. Bekleme eşiği Dkx ayarlarında ayarlanır.",
  "uk": "Усі, хто писав останнім, уже отримали відповідь. Поріг очікування змінюється в налаштуваннях Dkx.",
  "uz": "Oxirgi boʻlib yozganlarning hammasi javob olgan. Kutish chegarasi Dkx sozlamalarida sozlanadi."
 },
