  "be": "Спраў пакуль няма. Націсніце плюс уверсе, каб дадаць першую.",
  "ca": "Encara no hi ha tasques. Toqueu el + de dalt per a afegir-ne la primera.",
  "de": "Noch keine Aufgaben. Tippe oben auf Plus, um die erste hinzuzufügen.",
  "en": "No tasks yet. Tap plus at the top to add the first one.",
  "es": "Aún no hay tareas. Toca el + de arriba para añadir la primera.",
  "fa": "هنوز کاری نیست. برای افزودن اولین کار، روی + در بالا بزنید.",
  "fr": "Aucune tâche pour l'instant. Touchez le plus en haut pour ajouter la première.",
  "id": "Belum ada tugas. Ketuk plus di atas untuk menambahkan yang pertama.",
  "it": "Ancora nessuna attività. Tocca + in alto per aggiungere la prima.",
  "ko": "아직 할 일이 없습니다. 위의 +를 탭해 첫 할 일을 추가하세요.",
