  "nl": "Nog geen taken. Tik bovenaan op plus om de eerste toe te voegen.",
  "pl": "Nie ma jeszcze zadań. Stuknij plus u góry, aby dodać pierwsze.",
  "pt": "Ainda não há tarefas. Toque no sinal de mais no topo para adicionar a primeira.",
