 "Записей {}. Хранятся в Keychain только на этом телефоне и не уходят ни на сервер Telegram, ни в iCloud.": {
  "ar": "عدد السجلات {}. تُحفظ في Keychain على هذا الهاتف فقط ولا تُرسل إلى خادم Telegram ولا إلى iCloud.",
  "be": "Запісаў {}. Захоўваюцца ў Keychain толькі на гэтым тэлефоне і не ідуць ні на сервер Telegram, ні ў iCloud.",
  "ca": "Entrades {}. Es desen a Keychain només en aquest telèfon i no s'envien mai ni al servidor de Telegram ni a iCloud.",
  "de": "{} gespeichert. Sie liegen nur auf diesem Telefon im Keychain und gehen weder an den Telegram-Server noch an iCloud.",
  "en": "{} saved. Stored in Keychain on this phone only and never sent to Telegram's server or iCloud.",
  "es": "Entradas {}. Se guardan en Keychain solo en este teléfono y nunca se envían al servidor de Telegram ni a iCloud.",
  "fa": "{} مورد. فقط روی همین گوشی در Keychain نگهداری می‌شوند و نه به سرور Telegram می‌روند و نه به iCloud.",
  "fr": "{} entrée(s). Elles sont stockées dans le Keychain uniquement sur ce téléphone et ne sont envoyées ni au serveur Telegram ni à iCloud.",
  "id": "Entri {}. Disimpan di Keychain hanya di ponsel ini dan tidak dikirim ke server Telegram maupun iCloud.",
  "it": "Voci {}. Sono salvate in Keychain solo su questo telefono e non vanno mai né al server di Telegram né su iCloud.",
  "ko": "항목 {}개. 이 휴대폰의 Keychain에만 저장되며 Telegram 서버나 iCloud로 전송되지 않습니다.",
  "ms": "Entri {}. Disimpan dalam Keychain hanya pada telefon ini dan tidak dihantar ke pelayan Telegram atau iCloud.",
  "nl": "{} opgeslagen. Ze staan alleen op deze telefoon in de Keychain en gaan niet naar de Telegram-server en ook niet naar iCloud.",
  "pl": "Wpisów {}. Są przechowywane w Keychain tylko na tym telefonie i nie trafiają ani na serwer Telegram, ani do iCloud.",
  "pt": "Registros {}. Ficam no Keychain só neste celular e não vão para o servidor do Telegram nem para o iCloud.",
  "tr": "{} kayıt. Yalnızca bu telefondaki Keychain'de saklanır, ne Telegram sunucusuna ne de iCloud'a gönderilir.",
  "uk": "Записів {}. Зберігаються в Keychain лише на цьому телефоні й не йдуть ні на сервер Telegram, ні в iCloud.",
  "uz": "Yozuvlar {}. Ular faqat shu telefondagi Keychainda saqlanadi va Telegram serveriga ham, iCloudga ham yuborilmaydi."
 },
 "Записей пока нет. Все поля необязательны, но хотя бы одно нужно заполнить.": {
  "ar": "لا سجلات بعد. كل الحقول اختيارية، لكن يجب ملء حقل واحد على الأقل.",
  "be": "Запісаў пакуль няма. Усе палі неабавязковыя, але хаця б адно трэба запоўніць.",
  "ca": "Encara no hi ha entrades. Tots els camps són opcionals, però n'heu d'omplir almenys un.",
  "de": "Noch keine Einträge. Alle Felder sind optional, aber mindestens eines muss ausgefüllt sein.",
  "en": "No entries yet. All fields are optional, but at least one must be filled in.",
  "es": "Aún no hay entradas. Todos los campos son opcionales, pero hay que rellenar al menos uno.",
  "fa": "هنوز موردی نیست. همه فیلدها اختیاری‌اند، اما دست‌کم یکی باید پر شود.",
  "fr": "Aucune entrée pour l'instant. Tous les champs sont facultatifs, mais au moins un doit être rempli.",
  "id": "Belum ada entri. Semua kolom opsional, tapi minimal satu harus diisi.",
  "it": "Ancora nessuna voce. Tutti i campi sono facoltativi, ma almeno uno va compilato.",
  "ko": "아직 항목이 없습니다. 모든 필드는 선택 사항이지만 하나 이상은 입력해야 합니다.",
  "ms": "Belum ada entri. Semua medan adalah pilihan, tetapi sekurang-kurangnya satu perlu diisi.",
  "nl": "Nog geen items. Alle velden zijn optioneel, maar er moet er minstens één ingevuld zijn.",
  "pl": "Nie ma jeszcze wpisów. Wszystkie pola są opcjonalne, ale przynajmniej jedno trzeba wypełnić.",
  "pt": "Ainda não há registros. Todos os campos são opcionais, mas pelo menos um precisa ser preenchido.",
  "tr": "Henüz kayıt yok. Tüm alanlar isteğe bağlıdır, ancak en az biri doldurulmalıdır.",
  "uk": "Записів поки немає. Усі поля необовʼязкові, але хоча б одне треба заповнити.",
  "uz": "Hozircha yozuvlar yoʻq. Barcha maydonlar ixtiyoriy, lekin kamida bittasini toʻldirish kerak."
 },
