 "Запись хранится в Keychain только на этом телефоне.": {
  "ar": "يُحفظ السجل في Keychain على هذا الهاتف فقط.",
  "be": "Запіс захоўваецца ў Keychain толькі на гэтым тэлефоне.",
  "ca": "L'entrada es desa a Keychain només en aquest telèfon.",
  "de": "Der Eintrag liegt nur auf diesem Telefon im Keychain.",
  "en": "The entry is stored in Keychain on this phone only.",
  "es": "La entrada se guarda en Keychain solo en este teléfono.",
  "fa": "این مورد فقط روی همین گوشی در Keychain نگهداری می‌شود.",
  "fr": "L'entrée est stockée dans le Keychain uniquement sur ce téléphone.",
  "id": "Entri disimpan di Keychain hanya di ponsel ini.",
  "it": "La voce è salvata in Keychain solo su questo telefono.",
  "ko": "이 항목은 이 휴대폰의 Keychain에만 저장됩니다.",
  "ms": "Entri disimpan dalam Keychain hanya pada telefon ini.",
  "nl": "Het item staat alleen op deze telefoon in de Keychain.",
  "pl": "Wpis jest przechowywany w Keychain tylko na tym telefonie.",
  "pt": "O registro fica no Keychain só neste celular.",
  "tr": "Kayıt yalnızca bu telefondaki Keychain'de saklanır.",
  "uk": "Запис зберігається в Keychain лише на цьому телефоні.",
  "uz": "Yozuv faqat shu telefondagi Keychainda saqlanadi."
 },
 "Заполните хотя бы одно поле, иначе сохранять нечего.": {
  "ar": "املأ حقلًا واحدًا على الأقل، وإلا فلا شيء للحفظ.",
  "be": "Запоўніце хаця б адно поле, інакш захоўваць няма чаго.",
  "ca": "Ompliu almenys un camp, si no, no hi ha res a desar.",
  "de": "Fülle mindestens ein Feld aus, sonst gibt es nichts zu speichern.",
  "en": "Fill in at least one field, otherwise there's nothing to save.",
  "es": "Rellena al menos un campo, si no, no hay nada que guardar.",
  "fa": "دست‌کم یک فیلد را پر کنید، وگرنه چیزی برای ذخیره نیست.",
  "fr": "Remplissez au moins un champ, sinon il n'y a rien à enregistrer.",
  "id": "Isi minimal satu kolom, kalau tidak, tidak ada yang bisa disimpan.",
  "it": "Compila almeno un campo, altrimenti non c'è niente da salvare.",
  "ko": "필드를 하나 이상 입력하세요. 그렇지 않으면 저장할 내용이 없습니다.",
  "ms": "Isi sekurang-kurangnya satu medan, jika tidak, tiada apa untuk disimpan.",
  "nl": "Vul minstens één veld in, anders valt er niets op te slaan.",
  "pl": "Wypełnij przynajmniej jedno pole, inaczej nie ma czego zapisać.",
  "pt": "Preencha pelo menos um campo, senão não há nada para salvar.",
  "tr": "En az bir alanı doldurun, yoksa kaydedilecek bir şey yok.",
  "uk": "Заповніть хоча б одне поле, інакше зберігати нічого.",
  "uz": "Kamida bitta maydonni toʻldiring, aks holda saqlaydigan narsa yoʻq."
 },
