 "Изменённых сообщений нет. Прежние версии сохраняются при включённой «Истории правок».": {
  "ar": "لا توجد رسائل معدّلة. تُحفظ الإصدارات السابقة عند تفعيل «حفظ سجل التعديلات».",
  "be": "Змененых паведамленняў няма. Ранейшыя версіі захоўваюцца, калі ўключана «Захоўваць гісторыю правак».",
  "ca": "No hi ha missatges editats. Les versions anteriors es desen mentre «Desa l'historial d'edicions» està activat.",
  "de": "Keine bearbeiteten Nachrichten. Frühere Versionen werden gespeichert, solange „Bearbeitungsverlauf speichern“ an ist.",
  "en": "No edited messages. Previous versions are saved while “Save edit history” is on.",
  "es": "No hay mensajes editados. Las versiones anteriores se guardan mientras «Guardar historial de ediciones» está activado.",
  "fa": "پیام ویرایش‌شده‌ای نیست. نسخه‌های قبلی وقتی «ذخیره تاریخچه ویرایش» روشن باشد ذخیره می‌شوند.",
  "fr": "Aucun message modifié. Les versions précédentes sont conservées tant que « Conserver l'historique des modifications » est activé.",
  "id": "Tidak ada pesan yang diedit. Versi sebelumnya disimpan saat “Riwayat edit” aktif.",
  "it": "Nessun messaggio modificato. Le versioni precedenti vengono salvate quando «Salva cronologia modifiche» è attivo.",
  "ko": "수정된 메시지가 없습니다. 이전 버전은 ‘수정 기록 저장’이 켜져 있을 때 저장됩니다.",
  "ms": "Tiada mesej yang disunting. Versi sebelumnya disimpan apabila “Sejarah suntingan” dihidupkan.",
  "nl": "Geen bewerkte berichten. Eerdere versies worden bewaard zolang “Bewerkgeschiedenis bewaren” aan staat.",
  "pl": "Brak edytowanych wiadomości. Poprzednie wersje są zapisywane, gdy włączone jest „Zapisuj historię edycji”.",
  "pt": "Não há mensagens editadas. As versões anteriores são salvas quando o “Histórico de edições” está ativado.",
  "tr": "Düzenlenmiş mesaj yok. Önceki sürümler “Düzenleme geçmişi” açıkken kaydedilir.",
  "uk": "Змінених повідомлень немає. Попередні версії зберігаються, коли ввімкнено «Зберігати історію змін».",
  "uz": "Tahrirlangan xabarlar yoʻq. Oldingi versiyalar “Tahrirlar tarixi” yoqilgan boʻlsa saqlanadi."
 },
