 "Маршрут {}{}. Метки можно перетащить, движение начнётся с трансляцией": {
  "ar": "المسار {}{}. يمكن سحب الدبابيس، وتبدأ الحركة مع مشاركة الموقع الحي",
  "be": "Маршрут {}{}. Меткі можна перацягнуць, рух пачнецца з трансляцыяй",
  "ca": "Ruta {}{}. Els marcadors es poden arrossegar, el moviment començarà amb la ubicació en directe",
  "de": "Route {}{}. Die Markierungen lassen sich verschieben, die Bewegung startet mit dem Live-Standort",
  "en": "Route {}{}. Pins can be dragged, movement starts with live location",
  "es": "Ruta {}{}. Los marcadores se pueden arrastrar, el movimiento empezará con la ubicación en tiempo real",
  "fa": "مسیر {}{}. نشانگرها را می‌توان کشید، حرکت با موقعیت مکانی لحظه‌ای شروع می‌شود",
  "fr": "Itinéraire {}{}. Les repères peuvent être déplacés, le trajet démarre avec la position en direct",
  "id": "Rute {}{}. Penanda bisa digeser, pergerakan dimulai bersama Live Location",
  "it": "Percorso {}{}. I segnaposto si possono trascinare, il movimento partirà con la posizione in tempo reale",
  "ko": "경로 {}{}. 핀을 끌어서 옮길 수 있으며, 실시간 위치 공유를 시작하면 이동이 시작됩니다",
  "ms": "Laluan {}{}. Penanda boleh diseret, pergerakan bermula dengan Lokasi Langsung",
  "nl": "Route {}{}. De markeringen kun je verslepen, de beweging start met de live locatie",
  "pl": "Trasa {}{}. Znaczniki można przeciągać, ruch zacznie się razem z udostępnianiem na żywo",
  "pt": "Rota {}{}. Os marcadores podem ser arrastados, o movimento começa com a localização ao vivo",
  "tr": "Rota {}{}. İşaretçiler sürüklenebilir, hareket canlı konumla başlar",
  "uk": "Маршрут {}{}. Мітки можна перетягнути, рух почнеться з трансляцією",
  "uz": "Yoʻnalish {}{}. Belgilarni surish mumkin, harakat jonli joylashuv bilan boshlanadi"
