 "Метка «сохранил»": {
  "ar": "شارة «حفظك»",
  "be": "Метка «захаваў»",
  "ca": "Etiqueta «Us ha desat»",
  "de": "Label „Hat dich gespeichert“",
  "en": "“Saved you” label",
  "es": "Etiqueta «Te guardó»",
  "fa": "نشان «ذخیره کرده»",
  "fr": "Étiquette « Vous a enregistré »",
  "id": "Label “menyimpan Anda”",
  "it": "Etichetta «Ti ha salvato»",
  "ko": "‘저장함’ 배지",
  "ms": "Label “menyimpan anda”",
  "nl": "Label “Heeft je opgeslagen”",
  "pl": "Etykieta „zapisał cię”",
  "pt": "Etiqueta “salvou você”",
  "tr": "“Kaydetti” işareti",
  "uk": "Мітка «зберіг»",
  "uz": "“Saqlagan” belgisi"
 },
 "Метка «сохранил» или «не сохранил» видна в шапке чата и в профиле собеседника, только для тех, кого вы сами сохранили.\n\nЗаметка в шапке чата это первая строка вашей заметки из профиля собеседника. Правится в профиле через «Изменить».\n\nШаблоны вставляются кнопкой в поле ввода, она появляется после добавления первого шаблона. «Все сообщения автора» есть в меню долгого нажатия на сообщение в группе. «Выгрузить чат в файл» в профиле собеседника, группы или канала. Там вся история текстом, с пометками удалённых и прежними версиями изменённых.\n\nБез сжатия фото и видео из галереи уходят оригиналом, файлом, как через «Отправить файлом». Получатель увидит файл, а не картинку в ленте. Предел размера 2 ГБ держит сервер Telegram, его не поднять.\n\nFace ID на чат ставится долгим нажатием на чат в списке, пункт «Закрыть Face ID». У закрытого чата скрыт текст последнего сообщения и предпросмотр, открывается он после проверки и снова закрывается, когда приложение уходит в фон. Снять замок или выключить эту настройку можно только после проверки.\n\n«Мои дела» открываются из главных настроек, строка под «Моим профилем». Вид меняется кнопкой вверху, это лента, день по часам и месяц. Выключенный тумблер прячет строку, сами дела и напоминания остаются. «Пароли» там же, открываются по Face ID, записи лежат в Keychain только на этом телефоне.\n\n«Напомнить позже» есть в меню долгого нажатия на чат в списке и на сообщение. Напоминание ложится делом в «Мои дела», уведомление открывает этот чат.\n\nВключённое или выключенное применяется при следующем открытии экрана.": {
  "ar": "تظهر شارة «حفظك» أو «لم يحفظك» في رأس المحادثة وفي الملف الشخصي للطرف الآخر، فقط لمن حفظتهم أنت بنفسك.\n\nالملاحظة في رأس المحادثة هي السطر الأول من ملاحظتك في الملف الشخصي للطرف الآخر. تُعدَّل في الملف الشخصي عبر «تحرير».\n\nتُدرج القوالب بزر في حقل الإدخال، ويظهر الزر بعد إضافة أول قالب. «كل رسائل المرسل» موجود في قائمة الضغط المطوّل على رسالة في مجموعة. «تصدير المحادثة إلى ملف» موجود في الملف الشخصي للطرف الآخر أو المجموعة أو القناة. يحتوي الملف على السجل كاملًا نصًا، مع تمييز الرسائل المحذوفة والإصدارات السابقة للرسائل المعدّلة.\n\nدون ضغط، تُرسل الصور ومقاطع الفيديو من المعرض بجودتها الأصلية كملف، كما في «إرسال كملف». سيرى المستلم ملفًا لا صورة في المحادثة. حد الحجم 2 غيغابايت يفرضه خادم Telegram ولا يمكن رفعه.\n\nيُضبط Face ID على محادثة بالضغط المطوّل عليها في القائمة واختيار «قفل بـ Face ID». في المحادثة المقفلة يُخفى نص آخر رسالة والمعاينة، وتُفتح بعد التحقق وتُقفل مجددًا عندما ينتقل التطبيق إلى الخلفية. لا يمكن إزالة القفل أو إيقاف هذا الإعداد إلا بعد التحقق.\n\nتُفتح «مهامي» من الإعدادات الرئيسية، في الصف أسفل «ملفي الشخصي». يُغيَّر العرض بالزر في الأعلى، وهو القائمة واليوم بالساعات والشهر. إيقاف المفتاح يُخفي الصف، وتبقى المهام والتذكيرات نفسها. «كلمات المرور» هناك أيضًا، تُفتح بـ Face ID، والسجلات محفوظة في Keychain على هذا الهاتف فقط.\n\n«ذكّرني لاحقًا» موجود في قائمة الضغط المطوّل على محادثة في القائمة وعلى رسالة. يصبح التذكير مهمة في «مهامي»، ويفتح الإشعار تلك المحادثة.\n\nيُطبَّق التفعيل أو الإيقاف عند فتح الشاشة في المرة التالية.",
  "be": "Метку «захаваў» або «не захаваў» відаць у шапцы чата і ў профілі суразмоўцы, толькі для тых, каго вы самі захавалі.\n\nНататка ў шапцы чата гэта першы радок вашай нататкі з профілю суразмоўцы. Правіцца ў профілі праз «Рэдагаваць».\n\nШаблоны ўстаўляюцца кнопкай у полі ўводу, яна з'яўляецца пасля дадавання першага шаблона. «Усе паведамленні аўтара» ёсць у меню доўгага націску на паведамленне ў групе. «Выгрузіць чат у файл» ёсць у профілі суразмоўцы, групы або канала. Там уся гісторыя тэкстам, з пазнакамі выдаленых і ранейшымі версіямі змененых.\n\nБез сціскання фота і відэа з галерэі ідуць арыгіналам, файлам, як праз «Адправіць як файл». Атрымальнік убачыць файл, а не карцінку ў чаце. Мяжу памеру 2 ГБ трымае сервер Telegram, яе не падняць.\n\nFace ID на чат ставіцца доўгім націскам на чат у спісе, пункт «Закрыць на Face ID». У закрытага чата схаваны тэкст апошняга паведамлення і папярэдні прагляд, адкрываецца ён пасля праверкі і зноў закрываецца, калі праграма сыходзіць у фон. Зняць замок або выключыць гэту наладу можна толькі пасля праверкі.\n\n«Мае справы» адкрываюцца з галоўных налад, радок пад «Маім профілем». Выгляд мяняецца кнопкай уверсе, гэта стужка, дзень па гадзінах і месяц. Выключаны пераключальнік хавае радок, самі справы і нагадванні застаюцца. «Паролі» там жа, адкрываюцца па Face ID, запісы ляжаць у Keychain толькі на гэтым тэлефоне.\n\n«Нагадаць пазней» ёсць у меню доўгага націску на чат у спісе і на паведамленне. Нагадванне кладзецца справай у «Мае справы», апавяшчэнне адкрывае гэты чат.\n\nУключанае або выключанае прымяняецца пры наступным адкрыцці экрана.",
  "ca": "L'etiqueta «Us ha desat» o «No us ha desat» es veu a la capçalera del xat i al perfil del contacte, només per a les persones que teniu desades.\n\nLa nota a la capçalera del xat és la primera línia de la vostra nota del perfil del contacte. Es modifica al perfil amb «Edita».\n\nLes plantilles s'insereixen amb un botó al camp de text, que apareix després d'afegir la primera plantilla. «Tots els missatges de l'autor» és al menú que s'obre en mantenir premut un missatge en un grup. «Exporta el xat a un fitxer» és al perfil del contacte, del grup o del canal. Hi ha tot l'historial com a text, amb els missatges suprimits marcats i les versions anteriors dels editats.\n\nSense compressió, les fotos i els vídeos de la galeria s'envien en original, com a fitxer, igual que amb «Envia com a fitxer». El destinatari veurà un fitxer, no una imatge al xat. El límit de mida de 2 GB l'imposa el servidor de Telegram i no es pot augmentar.\n\nEl Face ID d'un xat es posa mantenint premut el xat a la llista, opció «Bloca amb Face ID». En un xat blocat s'amaguen el text de l'últim missatge i la previsualització, s'obre després de la verificació i es torna a blocar quan l'aplicació passa a segon pla. Treure el bloqueig o desactivar aquesta opció només es pot fer després de la verificació.\n\n«Les meves tasques» s'obre des de la configuració principal, a la fila sota «El meu perfil». La vista es canvia amb el botó de dalt, pot ser llista, dia per hores o mes. L'interruptor desactivat amaga la fila, les tasques i els recordatoris es mantenen. «Contrasenyes» és al mateix lloc, s'obre amb Face ID i les entrades es desen a Keychain només en aquest telèfon.\n\n«Recorda-m'ho més tard» és al menú que s'obre en mantenir premut un xat de la llista o un missatge. El recordatori es desa com a tasca a «Les meves tasques» i la notificació obre aquest xat.\n\nEl que activeu o desactiveu s'aplica la pròxima vegada que s'obri la pantalla.",
  "de": "Das Label „Hat dich gespeichert“ oder „Hat dich nicht gespeichert“ erscheint in der Chat-Kopfzeile und im Profil der anderen Person, nur bei denen, die du selbst gespeichert hast.\n\nDie Notiz in der Chat-Kopfzeile ist die erste Zeile deiner Notiz aus dem Profil der anderen Person. Bearbeitet wird sie im Profil über „Bearbeiten“.\n\nVorlagen fügst du mit einem Button im Eingabefeld ein, er erscheint, sobald die erste Vorlage angelegt ist. „Alle Nachrichten des Autors“ steht im Menü, das sich bei langem Drücken auf eine Nachricht in einer Gruppe öffnet. „Chat als Datei exportieren“ findest du im Profil einer Person, einer Gruppe oder eines Kanals. Darin steht der ganze Verlauf als Text, mit Vermerken bei gelöschten Nachrichten und den früheren Versionen bearbeiteter Nachrichten.\n\nOhne Komprimierung gehen Fotos und Videos aus der Galerie im Original als Datei raus, wie über „Als Datei senden“. Der Empfänger sieht eine Datei, kein Bild im Chat. Das Größenlimit von 2 GB setzt der Telegram-Server, es lässt sich nicht erhöhen.\n\nFace ID für einen Chat setzt du durch langes Drücken auf den Chat in der Liste, Punkt „Mit Face ID sperren“. Bei einem gesperrten Chat sind der Text der letzten Nachricht und die Vorschau verborgen, er öffnet sich nach der Prüfung und sperrt sich wieder, wenn die App in den Hintergrund geht. Die Sperre entfernen oder diese Einstellung ausschalten geht nur nach der Prüfung.\n\n„Meine Aufgaben“ öffnest du aus den Haupteinstellungen, in der Zeile unter „Mein Profil“. Die Ansicht wechselst du mit dem Button oben, zur Wahl stehen Liste, Tag nach Stunden und Monat. Ein ausgeschalteter Schalter blendet die Zeile aus, die Aufgaben und Erinnerungen bleiben erhalten. „Passwörter“ findest du ebenfalls dort, sie öffnen sich mit Face ID, die Einträge liegen nur auf diesem Telefon im Keychain.\n\n„Später erinnern“ steht im Menü, das sich bei langem Drücken auf einen Chat in der Liste oder auf eine Nachricht öffnet. Die Erinnerung wird als Aufgabe in „Meine Aufgaben“ angelegt, die Mitteilung öffnet diesen Chat.\n\nEin- und Ausschalten wird beim nächsten Öffnen des Bildschirms übernommen.",
  "en": "The “Saved you” or “Hasn't saved you” label appears in the chat header and in the contact's profile, only for people you have saved yourself.\n\nThe note in the chat header is the first line of your note from the contact's profile. Edit it in the profile via “Edit”.\n\nTemplates are inserted with a button in the input field, it appears after you add the first template. “All messages from author” is in the long-press menu of a message in a group. “Export chat to file” is in the profile of a contact, group or channel. It contains the whole history as text, with deleted messages marked and previous versions of edited ones.\n\nWithout compression, photos and videos from the gallery are sent as originals, as files, like “Send as File”. The recipient sees a file, not a picture in the chat. The 2 GB size limit is enforced by Telegram's server and can't be raised.\n\nFace ID for a chat is set by long-pressing the chat in the list and choosing “Lock with Face ID”. A locked chat hides the last message text and preview, opens after verification and locks again when the app goes to the background. Removing the lock or turning off this setting requires verification.\n\n“My Tasks” opens from the main settings, the row under “My Profile”. The view is switched with the button at the top, it's the feed, day by hour and month. Turning the switch off hides the row, the tasks and reminders stay. “Passwords” is there too, opens with Face ID, entries are stored in Keychain on this phone only.\n\n“Remind me later” is in the long-press menu of a chat in the list and of a message. The reminder becomes a task in “My Tasks”, the notification opens that chat.\n\nTurning things on or off applies the next time the screen opens.",
  "es": "La etiqueta «Te guardó» o «No te guardó» aparece en la cabecera del chat y en el perfil del contacto, solo para las personas que has guardado tú.\n\nLa nota en la cabecera del chat es la primera línea de tu nota del perfil del contacto. Se edita en el perfil con «Editar».\n\nLas plantillas se insertan con un botón en el campo de texto, que aparece después de añadir la primera plantilla. «Todos los mensajes del autor» está en el menú que se abre al mantener pulsado un mensaje en un grupo. «Exportar chat a un archivo» está en el perfil del contacto, grupo o canal. Ahí está todo el historial como texto, con los mensajes eliminados marcados y las versiones anteriores de los editados.\n\nSin compresión, las fotos y los videos de la galería se envían en su original, como archivo, igual que con «Enviar como archivo». El destinatario verá un archivo, no una imagen en el chat. El límite de tamaño de 2 GB lo impone el servidor de Telegram y no se puede ampliar.\n\nEl Face ID de un chat se pone manteniendo pulsado el chat en la lista, opción «Bloquear con Face ID». En un chat bloqueado se ocultan el texto del último mensaje y la vista previa, se abre tras la verificación y se vuelve a bloquear cuando la app pasa a segundo plano. Quitar el bloqueo o desactivar este ajuste solo es posible tras la verificación.\n\n«Mis tareas» se abre desde los ajustes principales, en la fila debajo de «Mi perfil». La vista se cambia con el botón de arriba, puede ser lista, día por horas o mes. El interruptor desactivado oculta la fila, las tareas y los recordatorios se conservan. «Contraseñas» está en el mismo sitio, se abre con Face ID y las entradas se guardan en Keychain solo en este teléfono.\n\n«Recordar más tarde» está en el menú que se abre al mantener pulsado un chat de la lista o un mensaje. El recordatorio se guarda como tarea en «Mis tareas» y la notificación abre ese chat.\n\nLo que actives o desactives se aplica la próxima vez que se abra la pantalla.",
  "fa": "نشان «ذخیره کرده» یا «ذخیره نکرده» در سربرگ گفتگو و در پروفایل طرف مقابل دیده می‌شود، فقط برای کسانی که خودتان ذخیره کرده‌اید.\n\nیادداشت در سربرگ گفتگو، خط اول یادداشت شما در پروفایل طرف مقابل است. در پروفایل با «ویرایش» تغییر می‌کند.\n\nالگوها با دکمه‌ای در فیلد ورودی درج می‌شوند که پس از افزودن اولین الگو ظاهر می‌شود. «همه پیام‌های فرستنده» در منوی لمس طولانی روی پیام در گروه است. «خروجی گفتگو در فایل» در پروفایل طرف مقابل، گروه یا کانال است. در آن کل تاریخچه به‌صورت متن است، با علامت پیام‌های حذف‌شده و نسخه‌های قبلی پیام‌های ویرایش‌شده.\n\nبدون فشرده‌سازی، عکس‌ها و ویدیوهای گالری با کیفیت اصلی و به‌صورت فایل ارسال می‌شوند، مانند «ارسال به صورت فایل». گیرنده یک فایل می‌بیند، نه تصویر در گفتگو. سقف حجم 2 گیگابایت را سرور Telegram تعیین می‌کند و نمی‌شود آن را بالا برد.\n\nFace ID برای گفتگو با لمس طولانی روی گفتگو در فهرست و گزینه «قفل با Face ID» تنظیم می‌شود. در گفتگوی قفل‌شده متن آخرین پیام و پیش‌نمایش پنهان است، پس از تأیید باز می‌شود و وقتی برنامه به پس‌زمینه می‌رود دوباره قفل می‌شود. برداشتن قفل یا خاموش کردن این تنظیم فقط پس از تأیید ممکن است.\n\n«کارهای من» از تنظیمات اصلی باز می‌شود، در ردیف زیر «پروفایل من». نما با دکمه بالا عوض می‌شود، یعنی فهرست، روز ساعت به ساعت و ماه. کلید خاموش ردیف را پنهان می‌کند، اما خود کارها و یادآوری‌ها می‌مانند. «رمزهای عبور» هم همان‌جاست، با Face ID باز می‌شود و موارد فقط روی همین گوشی در Keychain هستند.\n\n«بعداً یادآوری کن» در منوی لمس طولانی روی گفتگو در فهرست و روی پیام است. یادآوری به‌صورت کار در «کارهای من» ثبت می‌شود و اعلان همان گفتگو را باز می‌کند.\n\nروشن یا خاموش کردن با باز شدن دوباره صفحه اعمال می‌شود.",
  "fr": "L'étiquette « Vous a enregistré » ou « Ne vous a pas enregistré » apparaît dans l'en-tête de la discussion et dans le profil de votre interlocuteur, uniquement pour les personnes que vous avez vous-même enregistrées.\n\nLa note dans l'en-tête de la discussion est la première ligne de votre note dans le profil de votre interlocuteur. Elle se modifie dans le profil via « Modifier ».\n\nLes modèles s'insèrent avec un bouton du champ de saisie, qui apparaît après l'ajout du premier modèle. « Tous les messages de l'auteur » se trouve dans le menu d'appui long sur un message dans un groupe. « Exporter la discussion dans un fichier » se trouve dans le profil d'une personne, d'un groupe ou d'un canal. On y trouve tout l'historique en texte, avec la mention des messages supprimés et les versions précédentes des messages modifiés.\n\nSans compression, les photos et vidéos de la galerie partent en original, en tant que fichier, comme avec « Envoyer en tant que fichier ». Le destinataire verra un fichier, pas une image dans la discussion. La limite de 2 Go est imposée par le serveur Telegram, impossible de l'augmenter.\n\nFace ID sur une discussion s'active par un appui long sur la discussion dans la liste, option « Verrouiller avec Face ID ». Une discussion verrouillée masque le texte du dernier message et l'aperçu, elle s'ouvre après vérification et se verrouille à nouveau quand l'app passe en arrière-plan. Retirer le verrou ou désactiver ce réglage n'est possible qu'après vérification.\n\n« Mes tâches » s'ouvre depuis les paramètres principaux, dans la ligne sous « Mon profil ». La vue se change avec le bouton en haut, au choix liste, jour par heure et mois. Un interrupteur désactivé masque la ligne, les tâches et rappels restent. « Mots de passe » se trouve au même endroit, s'ouvre avec Face ID, les entrées sont stockées dans le Keychain uniquement sur ce téléphone.\n\n« Me rappeler plus tard » se trouve dans le menu d'appui long sur une discussion de la liste et sur un message. Le rappel devient une tâche dans « Mes tâches », la notification ouvre cette discussion.\n\nL'activation ou la désactivation s'applique à la prochaine ouverture de l'écran.",
  "id": "Label “menyimpan Anda” atau “tidak menyimpan Anda” terlihat di bagian atas obrolan dan di profil lawan bicara, hanya untuk orang yang Anda simpan sendiri.\n\nCatatan di bagian atas obrolan adalah baris pertama catatan Anda dari profil lawan bicara. Catatan diubah di profil lewat “Edit”.\n\nTemplat disisipkan dengan tombol di kolom pesan, tombol itu muncul setelah templat pertama ditambahkan. “Semua pesan dari pengirim” ada di menu tekan dan tahan pada pesan di grup. “Ekspor obrolan ke berkas” ada di profil lawan bicara, grup, atau kanal. Isinya seluruh riwayat dalam bentuk teks, dengan tanda pada pesan yang dihapus dan versi sebelumnya dari pesan yang diedit.\n\nTanpa kompresi, foto dan video dari galeri dikirim dalam bentuk asli, sebagai berkas, seperti lewat “Kirim sebagai Berkas”. Penerima akan melihat berkas, bukan gambar di obrolan. Batas ukuran 2 GB ditetapkan server Telegram dan tidak bisa dinaikkan.\n\nFace ID untuk obrolan dipasang dengan menekan dan menahan obrolan di daftar, pilih “Kunci dengan Face ID”. Obrolan terkunci menyembunyikan teks pesan terakhir dan pratinjau, terbuka setelah verifikasi, dan terkunci lagi saat aplikasi masuk ke latar belakang. Melepas kunci atau mematikan pengaturan ini hanya bisa setelah verifikasi.\n\n“Tugas Saya” dibuka dari pengaturan utama, baris di bawah “Profil Saya”. Tampilan diganti dengan tombol di atas, yaitu daftar, hari per jam, dan bulan. Jika sakelar dimatikan, baris disembunyikan, tapi tugas dan pengingat tetap ada. “Kata Sandi” juga ada di sana, dibuka dengan Face ID, entrinya disimpan di Keychain hanya di ponsel ini.\n\n“Ingatkan nanti” ada di menu tekan dan tahan pada obrolan di daftar dan pada pesan. Pengingat menjadi tugas di “Tugas Saya”, dan notifikasinya membuka obrolan tersebut.\n\nPerubahan aktif atau nonaktif berlaku saat layar dibuka berikutnya.",
  "it": "L'etichetta «Ti ha salvato» o «Non ti ha salvato» compare nell'intestazione della chat e nel profilo del contatto, solo per le persone che hai salvato tu.\n\nLa nota nell'intestazione della chat è la prima riga della tua nota nel profilo del contatto. Si modifica nel profilo con «Modifica».\n\nI modelli si inseriscono con un pulsante nel campo di testo, che compare dopo aver aggiunto il primo modello. «Tutti i messaggi dell'autore» si trova nel menu che si apre tenendo premuto un messaggio in un gruppo. «Esporta chat in un file» si trova nel profilo del contatto, del gruppo o del canale. Contiene tutta la cronologia come testo, con i messaggi eliminati segnalati e le versioni precedenti di quelli modificati.\n\nSenza compressione, foto e video dalla galleria vengono inviati in originale, come file, proprio come con «Invia come file». Il destinatario vedrà un file, non un'immagine nella chat. Il limite di dimensione di 2 GB è imposto dal server di Telegram e non si può aumentare.\n\nIl Face ID su una chat si imposta tenendo premuta la chat nell'elenco e scegliendo «Blocca con Face ID». In una chat bloccata sono nascosti il testo dell'ultimo messaggio e l'anteprima, si apre dopo la verifica e si blocca di nuovo quando l'app va in background. Togliere il blocco o disattivare questa impostazione si può solo dopo la verifica.\n\n«Le mie attività» si aprono dalle impostazioni principali, nella riga sotto «Il mio profilo». La vista si cambia con il pulsante in alto, può essere elenco, giorno per ore o mese. L'interruttore disattivato nasconde la riga, le attività e i promemoria restano. «Password» si trova lì, si apre con Face ID e le voci sono salvate in Keychain solo su questo telefono.\n\n«Ricordamelo più tardi» si trova nel menu che si apre tenendo premuta una chat nell'elenco o un messaggio. Il promemoria diventa un'attività in «Le mie attività», e la notifica apre quella chat.\n\nCiò che attivi o disattivi si applica alla prossima apertura della schermata.",
  "ko": "‘저장함’ 또는 ‘저장 안 함’ 배지는 대화 상단과 상대방 프로필에 표시되며, 내가 직접 저장한 사람에게만 표시됩니다.\n\n대화 상단의 메모는 상대방 프로필에 적은 내 메모의 첫 줄입니다. 프로필에서 ‘편집’으로 수정합니다.\n\n템플릿은 입력창의 버튼으로 삽입하며, 이 버튼은 첫 템플릿을 추가하면 나타납니다. ‘작성자의 모든 메시지’는 그룹에서 메시지를 길게 누르면 나오는 메뉴에 있습니다. ‘대화 파일로 내보내기’는 상대방, 그룹, 채널 프로필에 있습니다. 전체 기록이 텍스트로 담기며, 삭제된 메시지 표시와 수정된 메시지의 이전 버전이 포함됩니다.\n\n압축 없이 보내면 갤러리의 사진과 동영상이 ‘파일로 보내기’처럼 원본 파일로 전송됩니다. 받는 사람에게는 대화 속 사진이 아니라 파일로 보입니다. 2GB 크기 제한은 Telegram 서버가 정한 것이라 늘릴 수 없습니다.\n\n대화별 Face ID는 목록에서 대화를 길게 누르고 ‘Face ID로 잠그기’를 선택하면 설정됩니다. 잠긴 대화는 마지막 메시지 텍스트와 미리보기가 숨겨지고, 인증 후 열리며 앱이 백그라운드로 가면 다시 잠깁니다. 잠금 해제나 이 설정 끄기는 인증 후에만 가능합니다.\n\n‘내 할 일’은 메인 설정의 ‘내 프로필’ 아래 행에서 엽니다. 보기는 위쪽 버튼으로 바꾸며 목록, 시간별 일정, 월 보기가 있습니다. 스위치를 끄면 행이 숨겨지지만 할 일과 리마인더는 그대로 남습니다. ‘비밀번호’도 같은 곳에 있으며 Face ID로 열리고, 항목은 이 휴대폰의 Keychain에만 저장됩니다.\n\n‘나중에 알림’은 목록에서 대화를 길게 누르거나 메시지를 길게 누르면 나오는 메뉴에 있습니다. 리마인더는 ‘내 할 일’에 할 일로 추가되고, 알림을 탭하면 해당 대화가 열립니다.\n\n켜기나 끄기는 다음에 화면을 열 때 적용됩니다.",
  "ms": "Label “menyimpan anda” atau “tidak menyimpan anda” kelihatan di bahagian atas bual dan dalam profil orang itu, hanya untuk orang yang anda sendiri simpan.\n\nNota di bahagian atas bual ialah baris pertama nota anda daripada profil orang itu. Ia disunting dalam profil melalui “Sunting”.\n\nTemplat disisipkan dengan butang di ruang mesej, butang itu muncul selepas templat pertama ditambah. “Semua mesej daripada pengirim” ada dalam menu tekan lama pada mesej dalam grup. “Eksport bual ke fail” ada dalam profil orang itu, grup atau saluran. Di situ ada seluruh sejarah dalam bentuk teks, dengan tanda pada mesej yang dihapus dan versi sebelumnya bagi mesej yang disunting.\n\nTanpa pemampatan, foto dan video dari galeri dihantar dalam bentuk asal, sebagai fail, seperti melalui “Kirim sebagai Fail”. Penerima akan melihat fail, bukan gambar dalam bual. Had saiz 2 GB ditetapkan oleh pelayan Telegram dan tidak boleh dinaikkan.\n\nFace ID pada bual dipasang dengan tekan lama pada bual dalam senarai, pilih “Kunci dengan Face ID”. Bual terkunci menyembunyikan teks mesej terakhir dan pratonton, dibuka selepas pengesahan, dan dikunci semula apabila aplikasi masuk ke latar belakang. Membuang kunci atau mematikan tetapan ini hanya boleh selepas pengesahan.\n\n“Tugasan Saya” dibuka dari tetapan utama, baris di bawah “Profil Saya”. Paparan ditukar dengan butang di atas, iaitu senarai, hari mengikut jam dan bulan. Jika suis dimatikan, baris disembunyikan, tetapi tugasan dan peringatan kekal. “Kata Laluan” juga di situ, dibuka dengan Face ID, entrinya disimpan dalam Keychain hanya pada telefon ini.\n\n“Ingatkan kemudian” ada dalam menu tekan lama pada bual dalam senarai dan pada mesej. Peringatan menjadi tugasan dalam “Tugasan Saya”, dan notifikasinya membuka bual itu.\n\nPerubahan hidup atau mati berkuat kuasa apabila skrin dibuka seterusnya.",
  "nl": "Het label “Heeft je opgeslagen” of “Heeft je niet opgeslagen” staat in de chatkop en in het profiel van de ander, alleen bij mensen die je zelf hebt opgeslagen.\n\nDe notitie in de chatkop is de eerste regel van je notitie in het profiel van de ander. Je past hem aan in het profiel via “Wijzig”.\n\nSjablonen voeg je in met een knop in het invoerveld, die verschijnt nadat je het eerste sjabloon hebt toegevoegd. “Alle berichten van auteur” staat in het menu dat opent als je lang op een bericht in een groep drukt. “Chat exporteren naar bestand” staat in het profiel van een persoon, groep of kanaal. Daarin staat de hele geschiedenis als tekst, met markeringen bij verwijderde berichten en eerdere versies van bewerkte berichten.\n\nZonder compressie gaan foto's en video's uit de galerij als origineel weg, als bestand, zoals via “Als bestand versturen”. De ontvanger ziet een bestand, geen afbeelding in de chat. De limiet van 2 GB komt van de Telegram-server en kan niet omhoog.\n\nFace ID voor een chat zet je door lang op de chat in de lijst te drukken, onderdeel “Vergrendelen met Face ID”. Bij een vergrendelde chat zijn de tekst van het laatste bericht en de voorvertoning verborgen, hij opent na verificatie en vergrendelt weer zodra de app naar de achtergrond gaat. Het slot verwijderen of deze instelling uitschakelen kan alleen na verificatie.\n\n“Mijn taken” open je vanuit de hoofdinstellingen, in de rij onder “Mijn profiel”. De weergave wissel je met de knop bovenaan, je kiest uit lijst, dag per uur en maand. Een uitgeschakelde schakelaar verbergt de rij, de taken en herinneringen blijven bestaan. “Wachtwoorden” staat daar ook, opent met Face ID, de items staan alleen op deze telefoon in de Keychain.\n\n“Later herinneren” staat in het menu dat opent als je lang op een chat in de lijst of op een bericht drukt. De herinnering wordt een taak in “Mijn taken”, de melding opent die chat.\n\nIn- of uitschakelen wordt toegepast als het scherm opnieuw wordt geopend.",
  "pl": "Etykieta „zapisał cię” lub „nie zapisał cię” jest widoczna w nagłówku czatu i w profilu rozmówcy, tylko dla osób zapisanych przez ciebie.\n\nNotatka w nagłówku czatu to pierwszy wiersz twojej notatki z profilu rozmówcy. Edytuje się ją w profilu przez „Edytuj”.\n\nSzablony wstawia się przyciskiem w polu wpisywania, pojawia się on po dodaniu pierwszego szablonu. „Wszystkie wiadomości autora” są w menu przytrzymania wiadomości w grupie. „Eksportuj czat do pliku” jest w profilu rozmówcy, grupy lub kanału. Jest tam cała historia jako tekst, z oznaczeniem usuniętych i poprzednimi wersjami edytowanych.\n\nBez kompresji zdjęcia i wideo z galerii są wysyłane w oryginale, jako plik, jak przez „Wyślij jako plik”. Odbiorca zobaczy plik, a nie obrazek w czacie. Limit rozmiaru 2 GB narzuca serwer Telegram, nie da się go podnieść.\n\nFace ID dla czatu ustawia się przez przytrzymanie czatu na liście, pozycja „Zablokuj przez Face ID”. Zablokowany czat ukrywa tekst ostatniej wiadomości i podgląd, otwiera się po weryfikacji i blokuje się ponownie, gdy aplikacja przechodzi w tło. Zdjęcie blokady lub wyłączenie tego ustawienia wymaga weryfikacji.\n\n„Moje zadania” otwierają się z głównych ustawień, wiersz pod „Moim profilem”. Widok zmienia się przyciskiem u góry, to lista, dzień godzinami i miesiąc. Wyłączony przełącznik ukrywa wiersz, same zadania i przypomnienia zostają. „Hasła” są tam również, otwierają się przez Face ID, wpisy są w Keychain tylko na tym telefonie.\n\n„Przypomnij później” jest w menu przytrzymania czatu na liście i wiadomości. Przypomnienie trafia jako zadanie do „Moich zadań”, powiadomienie otwiera ten czat.\n\nWłączenie lub wyłączenie działa przy następnym otwarciu ekranu.",
  "pt": "A etiqueta “salvou você” ou “não salvou você” aparece no topo do chat e no perfil da pessoa, só para quem você mesmo salvou.\n\nA nota no topo do chat é a primeira linha da sua nota no perfil da pessoa. Ela é editada no perfil, em “Editar”.\n\nOs modelos são inseridos pelo botão no campo de mensagem, que aparece depois que você adiciona o primeiro modelo. “Todas as mensagens do autor” fica no menu ao tocar e segurar uma mensagem no grupo. “Exportar chat para arquivo” fica no perfil da pessoa, do grupo ou do canal. Lá está todo o histórico em texto, com as apagadas marcadas e as versões anteriores das editadas.\n\nSem compressão, fotos e vídeos da galeria são enviados no original, como arquivo, igual a “Enviar Como Arquivo”. Quem recebe vê um arquivo, não uma imagem no chat. O limite de 2 GB é do servidor do Telegram e não dá para aumentar.\n\nO Face ID em um chat é ativado ao tocar e segurar o chat na lista, item “Bloquear com Face ID”. Um chat bloqueado esconde o texto da última mensagem e a prévia, abre após a verificação e bloqueia de novo quando o app vai para segundo plano. Remover o bloqueio ou desativar esta opção só é possível após a verificação.\n\n“Minhas Tarefas” abre pelas configurações principais, na linha abaixo de “Meu Perfil”. A visualização muda pelo botão no topo, são lista, dia por hora e mês. Com a opção desativada, a linha fica oculta, mas as tarefas e os lembretes continuam. “Senhas” fica no mesmo lugar, abre com Face ID, e os registros ficam no Keychain só neste celular.\n\n“Lembrar mais tarde” fica no menu ao tocar e segurar um chat na lista ou uma mensagem. O lembrete vira uma tarefa em “Minhas Tarefas”, e a notificação abre esse chat.\n\nO que for ativado ou desativado vale na próxima vez que a tela for aberta.",
  "tr": "“Kaydetti” veya “kaydetmedi” işareti sohbet başlığında ve karşı tarafın profilinde görünür, yalnızca kendi kaydettiğiniz kişiler için.\n\nSohbet başlığındaki not, karşı tarafın profilindeki notunuzun ilk satırıdır. Profilde “Düzenle” ile değiştirilir.\n\nŞablonlar giriş alanındaki bir düğmeyle eklenir, düğme ilk şablon eklendikten sonra görünür. “Yazarın tüm mesajları” bir gruptaki mesaja basılı tutunca açılan menüde bulunur. “Sohbeti dosyaya aktar” karşı tarafın, grubun veya kanalın profilindedir. Orada tüm geçmiş metin olarak, silinenler işaretli ve düzenlenenlerin önceki sürümleriyle yer alır.\n\nSıkıştırmasız modda galeriden fotoğraf ve videolar orijinal olarak, dosya şeklinde, “Dosya Olarak Gönder” ile olduğu gibi gider. Alıcı sohbette resim değil dosya görür. 2 GB boyut sınırını Telegram sunucusu koyar, yükseltilemez.\n\nBir sohbete Face ID, listede sohbete basılı tutup “Face ID ile kilitle” seçeneğiyle eklenir. Kilitli sohbette son mesajın metni ve önizleme gizlenir, sohbet doğrulamadan sonra açılır ve uygulama arka plana geçince yeniden kilitlenir. Kilidi kaldırmak veya bu ayarı kapatmak yalnızca doğrulamadan sonra mümkündür.\n\n“Görevlerim” ana ayarlardan, “Profilim” altındaki satırdan açılır. Görünüm üstteki düğmeyle değiştirilir, bunlar akış, saat saat gün ve ay. Anahtar kapalıyken satır gizlenir, görevlerin ve hatırlatıcıların kendisi kalır. “Parolalar” da orada, Face ID ile açılır, kayıtlar yalnızca bu telefondaki Keychain'de saklanır.\n\n“Daha sonra hatırlat” listedeki sohbete ve mesaja basılı tutunca açılan menüde bulunur. Hatırlatıcı “Görevlerim” içine görev olarak eklenir, bildirim bu sohbeti açar.\n\nAçma veya kapatma, ekran bir sonraki açıldığında uygulanır.",
  "uk": "Мітку «зберіг» або «не зберіг» видно в шапці чату й у профілі співрозмовника, лише для тих, кого ви самі зберегли.\n\nНотатка в шапці чату це перший рядок вашої нотатки з профілю співрозмовника. Редагується в профілі через «Редагувати».\n\nШаблони вставляються кнопкою в полі введення, вона зʼявляється після додавання першого шаблону. «Усі повідомлення автора» є в меню довгого натискання на повідомлення в групі. «Вивантажити чат у файл» є в профілі співрозмовника, групи чи каналу. Там уся історія текстом, з позначками видалених і попередніми версіями змінених.\n\nБез стиснення фото й відео з галереї йдуть оригіналом, файлом, як через «Надіслати як файл». Одержувач побачить файл, а не картинку в чаті. Межу розміру 2 ГБ тримає сервер Telegram, її не підняти.\n\nFace ID на чат ставиться довгим натисканням на чат у списку, пункт «Закрити на Face ID». У закритого чату приховано текст останнього повідомлення й попередній перегляд, відкривається він після перевірки й знову закривається, коли застосунок іде у фон. Зняти замок або вимкнути це налаштування можна лише після перевірки.\n\n«Мої справи» відкриваються з головних налаштувань, рядок під «Моїм профілем». Вигляд змінюється кнопкою вгорі, це стрічка, день по годинах і місяць. Вимкнений перемикач ховає рядок, самі справи й нагадування лишаються. «Паролі» там само, відкриваються за Face ID, записи лежать у Keychain лише на цьому телефоні.\n\n«Нагадати пізніше» є в меню довгого натискання на чат у списку й на повідомлення. Нагадування лягає справою в «Мої справи», сповіщення відкриває цей чат.\n\nУвімкнене чи вимкнене застосовується під час наступного відкриття екрана.",
  "uz": "“Saqlagan” yoki “saqlamagan” belgisi chat sarlavhasida va suhbatdosh profilida koʻrinadi, faqat oʻzingiz saqlagan odamlar uchun.\n\nChat sarlavhasidagi qayd bu suhbatdosh profilidagi qaydingizning birinchi qatori. U profilda “Tahrir” orqali oʻzgartiriladi.\n\nShablonlar kiritish maydonidagi tugma bilan qoʻyiladi, u birinchi shablon qoʻshilgandan keyin chiqadi. “Muallifning barcha xabarlari” guruhdagi xabarni bosib turganda chiqadigan menyuda bor. “Chatni faylga eksport qilish” suhbatdosh, guruh yoki kanal profilida. Unda butun tarix matn koʻrinishida, oʻchirilganlar belgilangan va tahrirlanganlarning oldingi versiyalari bilan.\n\nSiqishsiz rejimda galereyadagi rasm va videolar asl holida, fayl sifatida, “Fayl kabi yuborish” orqali yuborilgandek ketadi. Qabul qiluvchi chatda rasm emas, fayl koʻradi. 2 GB hajm chegarasini Telegram serveri belgilaydi, uni oshirib boʻlmaydi.\n\nChatga Face ID roʻyxatdagi chatni bosib turib, “Face ID bilan qulflash” bandi orqali qoʻyiladi. Qulflangan chatda oxirgi xabar matni va oldindan koʻrish berkitiladi, u tekshiruvdan keyin ochiladi va ilova fonga oʻtganda yana qulflanadi. Qulfni yechish yoki bu sozlamani oʻchirish faqat tekshiruvdan keyin mumkin.\n\n“Vazifalarim” asosiy sozlamalardan, “Profilim” ostidagi qatordan ochiladi. Koʻrinish yuqoridagi tugma bilan almashtiriladi, bular tasma, kun soatlar boʻyicha va oy. Oʻchirilgan holatda qator berkitiladi, vazifalar va eslatmalarning oʻzi qoladi. “Parollar” ham oʻsha yerda, Face ID bilan ochiladi, yozuvlar faqat shu telefondagi Keychainda saqlanadi.\n\n“Keyinroq eslatish” roʻyxatdagi chatni va xabarni bosib turganda chiqadigan menyuda bor. Eslatma “Vazifalarim”ga vazifa sifatida tushadi, bildirishnoma shu chatni ochadi.\n\nYoqish yoki oʻchirish ekran keyingi safar ochilganda qoʻllanadi."
 },
 "Метка ставится долгим нажатием на чат в списке, пункт «Метки». На одном чате может быть несколько меток, группы тоже подходят. Метки видны под именем чата и рядом над списком чатов, нажатие на метку открывает её чаты. Хранятся только на этом телефоне, собеседники их не видят.": {
  "ar": "يُضاف الوسم بالضغط المطوّل على محادثة في القائمة واختيار «الوسوم». يمكن أن تحمل المحادثة الواحدة عدة وسوم، والمجموعات أيضًا. تظهر الوسوم تحت اسم المحادثة وفي الصف فوق قائمة المحادثات، والضغط على وسم يفتح محادثاته. تُحفظ على هذا الهاتف فقط، ولا يراها الآخرون.",
  "be": "Метка ставіцца доўгім націскам на чат у спісе, пункт «Меткі». На адным чаце можа быць некалькі метак, групы таксама падыходзяць. Меткі відаць пад назвай чата і побач над спісам чатаў, націск на метку адкрывае яе чаты. Захоўваюцца толькі на гэтым тэлефоне, суразмоўцы іх не бачаць.",
  "ca": "Per a posar una etiqueta, manteniu premut el xat a la llista i trieu «Etiquetes». Un xat pot tenir diverses etiquetes, i els grups també hi serveixen. Les etiquetes es veuen sota el nom del xat i a la fila sobre la llista de xats, i en tocar una etiqueta s'obren els seus xats. Només es desen en aquest telèfon, les altres persones no les veuen.",
  "de": "Ein Label setzt du durch langes Drücken auf den Chat in der Liste, Punkt „Labels“. Ein Chat kann mehrere Labels haben, Gruppen gehen auch. Labels erscheinen unter dem Chatnamen und in der Leiste über der Chatliste, Tippen auf ein Label öffnet seine Chats. Sie liegen nur auf diesem Telefon, andere sehen sie nicht.",
  "en": "To label a chat, long-press it in the list and choose “Labels”. A chat can have several labels, groups work too. Labels appear under the chat name and in the row above the chat list, tapping a label opens its chats. They are stored only on this phone, other people don't see them.",
  "es": "Para poner una etiqueta, mantén pulsado el chat en la lista y elige «Etiquetas». Un chat puede tener varias etiquetas, y los grupos también sirven. Las etiquetas se ven bajo el nombre del chat y en la fila sobre la lista de chats, y al tocar una etiqueta se abren sus chats. Se guardan solo en este teléfono, las otras personas no las ven.",
  "fa": "برچسب با لمس طولانی روی گفتگو در فهرست و گزینه «برچسب‌ها» گذاشته می‌شود. یک گفتگو می‌تواند چند برچسب داشته باشد، گروه‌ها هم می‌توانند. برچسب‌ها زیر نام گفتگو و در ردیف بالای فهرست گفتگوها دیده می‌شوند و زدن روی برچسب، گفتگوهای آن را باز می‌کند. فقط روی همین گوشی ذخیره می‌شوند و دیگران آن‌ها را نمی‌بینند.",
  "fr": "Pour étiqueter une discussion, faites un appui long dessus dans la liste, option « Étiquettes ». Une discussion peut avoir plusieurs étiquettes, les groupes aussi. Les étiquettes apparaissent sous le nom de la discussion et dans la barre au-dessus de la liste des discussions, toucher une étiquette ouvre ses discussions. Elles sont stockées uniquement sur ce téléphone, vos interlocuteurs ne les voient pas.",
  "id": "Label dipasang dengan menekan dan menahan obrolan di daftar, pilih “Label”. Satu obrolan bisa punya beberapa label, grup juga bisa. Label terlihat di bawah nama obrolan dan di baris atas daftar obrolan, mengetuk label membuka obrolannya. Label hanya disimpan di ponsel ini, lawan bicara tidak melihatnya.",
  "it": "Per mettere un'etichetta, tieni premuta la chat nell'elenco e scegli «Etichette». Una chat può avere più etichette, e vanno bene anche i gruppi. Le etichette compaiono sotto il nome della chat e nella riga sopra l'elenco delle chat, e toccando un'etichetta si aprono le sue chat. Sono salvate solo su questo telefono, le altre persone non le vedono.",
  "ko": "목록에서 대화를 길게 누르고 ‘라벨’을 선택하면 라벨을 붙일 수 있습니다. 한 대화에 여러 라벨을 붙일 수 있으며 그룹도 가능합니다. 라벨은 대화 이름 아래와 대화 목록 위의 줄에 표시되며, 라벨을 탭하면 해당 대화들이 열립니다. 이 휴대폰에만 저장되며 상대방은 볼 수 없습니다.",
  "ms": "Label dipasang dengan tekan lama pada bual dalam senarai, pilih “Label”. Satu bual boleh ada beberapa label, grup juga boleh. Label kelihatan di bawah nama bual dan pada baris di atas senarai bual, menekan label membuka bualnya. Label hanya disimpan pada telefon ini, orang lain tidak melihatnya.",
  "nl": "Een label zet je door lang op de chat in de lijst te drukken, onderdeel “Labels”. Een chat kan meerdere labels hebben, groepen kunnen ook. Labels staan onder de chatnaam en in de balk boven de chatlijst, tikken op een label opent de chats ervan. Ze worden alleen op deze telefoon bewaard, anderen zien ze niet.",
  "pl": "Etykietę dodaje się przez przytrzymanie czatu na liście, pozycja „Etykiety”. Jeden czat może mieć kilka etykiet, grupy też się nadają. Etykiety widać pod nazwą czatu i w wierszu nad listą czatów, stuknięcie etykiety otwiera jej czaty. Są przechowywane tylko na tym telefonie, rozmówcy ich nie widzą.",
  "pt": "Para colocar uma etiqueta, toque e segure o chat na lista e escolha “Etiquetas”. Um chat pode ter várias etiquetas, grupos também funcionam. As etiquetas aparecem abaixo do nome do chat e na linha acima da lista de chats, e tocar em uma etiqueta abre os chats dela. Ficam só neste celular, as outras pessoas não as veem.",
  "tr": "Etiket, listedeki sohbete basılı tutup “Etiketler” seçeneğiyle eklenir. Bir sohbette birden fazla etiket olabilir, gruplar da olur. Etiketler sohbet adının altında ve sohbet listesinin üstündeki satırda görünür, etikete dokunmak onun sohbetlerini açar. Yalnızca bu telefonda saklanır, karşı taraf bunları görmez.",
  "uk": "Мітка ставиться довгим натисканням на чат у списку, пункт «Мітки». На одному чаті може бути кілька міток, групи теж підходять. Мітки видно під назвою чату й поруч над списком чатів, натискання на мітку відкриває її чати. Зберігаються лише на цьому телефоні, співрозмовники їх не бачать.",
  "uz": "Yorliq roʻyxatdagi chatni bosib turib, “Yorliqlar” bandi orqali qoʻyiladi. Bitta chatda bir nechta yorliq boʻlishi mumkin, guruhlar ham mos keladi. Yorliqlar chat nomi ostida va chatlar roʻyxati ustidagi qatorda koʻrinadi, yorliqni bosish uning chatlarini ochadi. Ular faqat shu telefonda saqlanadi, suhbatdoshlar ularni koʻrmaydi."
 },
 "Метки": {
