 "Метки видны рядом под заголовком Избранного, нажатие на метку показывает её сообщения. Название, цвет и порядок меняются там же, кнопкой «Изменить». Метки хранятся на этом телефоне и не пропадают при переустановке.": {
  "ar": "تظهر الوسوم في الصف أسفل عنوان الرسائل المحفوظة، والضغط على وسم يعرض رسائله. يُغيَّر الاسم واللون والترتيب هناك أيضًا بزر «تحرير». تُحفظ الوسوم على هذا الهاتف ولا تختفي عند إعادة تثبيت التطبيق.",
  "be": "Меткі відаць радком пад загалоўкам Захаванага, націск на метку паказвае яе паведамленні. Назва, колер і парадак мяняюцца там жа, кнопкай «Рэдагаваць». Меткі захоўваюцца на гэтым тэлефоне і не знікаюць пры пераўсталёўцы.",
  "ca": "Les etiquetes es veuen a la fila sota el títol de Missatges desats, i en tocar una etiqueta es mostren els seus missatges. El nom, el color i l'ordre es canvien allà mateix, amb el botó «Edita». Les etiquetes es desen en aquest telèfon i es conserven si reinstal·leu l'aplicació.",
  "de": "Labels erscheinen in der Leiste unter dem Titel „Gespeicherte Nachrichten“, Tippen auf ein Label zeigt seine Nachrichten. Name, Farbe und Reihenfolge änderst du ebenfalls dort, über den Button „Bearbeiten“. Die Labels liegen auf diesem Telefon und bleiben auch nach einer Neuinstallation erhalten.",
  "en": "Labels appear in the row under the Saved Messages title, tapping a label shows its messages. Name, color and order are changed there too, with the “Edit” button. Labels are stored on this phone and survive reinstalling the app.",
  "es": "Las etiquetas se ven en la fila bajo el título de Mensajes guardados, y al tocar una etiqueta se muestran sus mensajes. El nombre, el color y el orden se cambian ahí mismo, con el botón «Editar». Las etiquetas se guardan en este teléfono y se conservan al reinstalar la app.",
  "fa": "برچسب‌ها در ردیف زیر عنوان پیام‌های ذخیره شده دیده می‌شوند و زدن روی برچسب، پیام‌های آن را نشان می‌دهد. نام، رنگ و ترتیب همان‌جا با دکمه «ویرایش» تغییر می‌کند. برچسب‌ها روی همین گوشی ذخیره می‌شوند و با نصب دوباره برنامه از بین نمی‌روند.",
  "fr": "Les étiquettes apparaissent dans la barre sous le titre Messages enregistrés, toucher une étiquette affiche ses messages. Le nom, la couleur et l'ordre se modifient au même endroit, avec le bouton « Modifier ». Les étiquettes sont stockées sur ce téléphone et restent après une réinstallation de l'app.",
  "id": "Label terlihat di baris di bawah judul Pesan Tersimpan, mengetuk label menampilkan pesannya. Nama, warna, dan urutan juga diubah di sana, dengan tombol “Edit”. Label disimpan di ponsel ini dan tetap ada setelah aplikasi dipasang ulang.",
  "it": "Le etichette compaiono nella riga sotto il titolo di Messaggi salvati, e toccando un'etichetta si vedono i suoi messaggi. Nome, colore e ordine si cambiano lì, con il pulsante «Modifica». Le etichette sono salvate su questo telefono e restano anche se reinstalli l'app.",
  "ko": "라벨은 저장한 메시지 제목 아래의 줄에 표시되며, 라벨을 탭하면 해당 메시지들이 표시됩니다. 이름, 색상, 순서도 같은 곳에서 ‘편집’ 버튼으로 바꿀 수 있습니다. 라벨은 이 휴대폰에 저장되며 앱을 다시 설치해도 사라지지 않습니다.",
  "ms": "Label kelihatan pada baris di bawah tajuk Mesej Disimpan, menekan label menunjukkan mesejnya. Nama, warna dan susunan juga ditukar di situ, dengan butang “Sunting”. Label disimpan pada telefon ini dan kekal walaupun aplikasi dipasang semula.",
  "nl": "Labels staan in de balk onder de titel “Bewaarde berichten”, tikken op een label toont de berichten ervan. Naam, kleur en volgorde wijzig je daar ook, met de knop “Wijzig”. Labels worden op deze telefoon bewaard en blijven behouden als je de app opnieuw installeert.",
  "pl": "Etykiety widać w wierszu pod tytułem Zapisanych wiadomości, stuknięcie etykiety pokazuje jej wiadomości. Nazwę, kolor i kolejność zmienisz w tym samym miejscu przyciskiem „Edytuj”. Etykiety są przechowywane na tym telefonie i nie znikają po ponownej instalacji.",
  "pt": "As etiquetas aparecem na linha abaixo do título das Mensagens Salvas, e tocar em uma etiqueta mostra as mensagens dela. Nome, cor e ordem são alterados no mesmo lugar, pelo botão “Editar”. As etiquetas ficam neste celular e continuam lá mesmo se o app for reinstalado.",
  "tr": "Etiketler, Kayıtlı Mesajlar başlığının altındaki satırda görünür, etikete dokunmak onun mesajlarını gösterir. Ad, renk ve sıra da orada, “Düzenle” düğmesiyle değiştirilir. Etiketler bu telefonda saklanır ve uygulama yeniden yüklense de silinmez.",
  "uk": "Мітки видно рядком під заголовком Збереженого, натискання на мітку показує її повідомлення. Назва, колір і порядок змінюються там само, кнопкою «Редагувати». Мітки зберігаються на цьому телефоні й не зникають після перевстановлення.",
  "uz": "Yorliqlar “Saqlangan xabarlar” sarlavhasi ostidagi qatorda koʻrinadi, yorliqni bosish uning xabarlarini koʻrsatadi. Nomi, rangi va tartibi ham oʻsha yerda “Tahrirlash” tugmasi bilan oʻzgartiriladi. Yorliqlar shu telefonda saqlanadi va ilova qayta oʻrnatilganda ham yoʻqolmaydi."
 },
