  "it": "Ancora nessuna etichetta. Crea la prima, verrà applicata subito a «{}».",
  "ko": "아직 라벨이 없습니다. 첫 라벨을 만들면 바로 ‘{}’에 붙습니다.",
  "ms": "Belum ada label. Cipta yang pertama, ia terus dipasang pada “{}”.",
  "nl": "Nog geen labels. Maak het eerste, het wordt meteen op “{}” gezet.",
  "pl": "Nie ma jeszcze etykiet. Utwórz pierwszą, od razu trafi na „{}”.",
  "pt": "Ainda não há etiquetas. Crie a primeira, ela será aplicada a “{}” na hora.",
  "tr": "Henüz etiket yok. İlkini oluşturun, hemen “{}” sohbetine eklenecek.",
  "uk": "Міток поки немає. Створіть першу, її одразу буде поставлено на «{}».",
  "uz": "Hozircha yorliqlar yoʻq. Birinchisini yarating, u darhol “{}” chatiga qoʻyiladi."
