  "ms": "Belum ada label. Cipta yang pertama, ia terus dipasang pada mesej ini.",
  "nl": "Nog geen labels. Maak het eerste, het wordt meteen op dit bericht gezet.",
  "pl": "Nie ma jeszcze etykiet. Utwórz pierwszą, od razu trafi na tę wiadomość.",
  "pt": "Ainda não há etiquetas. Crie a primeira, ela será aplicada a esta mensagem na hora.",
  "tr": "Henüz etiket yok. İlkini oluşturun, hemen bu mesaja eklenecek.",
  "uk": "Міток поки немає. Створіть першу, її одразу буде поставлено на це повідомлення.",
  "uz": "Hozircha yorliqlar yoʻq. Birinchisini yarating, u darhol shu xabarga qoʻyiladi."
 },
