 "Нажатие открывает сообщение в Избранном. Снять метку можно долгим нажатием на сообщение, пункт «Метки».": {
  "ar": "الضغط يفتح الرسالة في الرسائل المحفوظة. لإزالة وسم، اضغط مطولًا على الرسالة واختر «الوسوم».",
  "be": "Націск адкрывае паведамленне ў Захаваным. Зняць метку можна доўгім націскам на паведамленне, пункт «Меткі».",
  "ca": "Toqueu un missatge per a obrir-lo a Missatges desats. Per a treure una etiqueta, manteniu premut el missatge i trieu «Etiquetes».",
  "de": "Tippen öffnet die Nachricht in den Gespeicherten Nachrichten. Ein Label entfernst du durch langes Drücken auf die Nachricht, Punkt „Labels“.",
  "en": "Tap to open the message in Saved Messages. To remove a label, long-press the message and choose “Labels”.",
  "es": "Toca un mensaje para abrirlo en Mensajes guardados. Para quitar una etiqueta, mantén pulsado el mensaje y elige «Etiquetas».",
  "fa": "زدن روی آن، پیام را در پیام‌های ذخیره شده باز می‌کند. برای برداشتن برچسب، روی پیام لمس طولانی کنید و «برچسب‌ها» را بزنید.",
  "fr": "Touchez pour ouvrir le message dans Messages enregistrés. Pour retirer une étiquette, faites un appui long sur le message, option « Étiquettes ».",
  "id": "Ketuk untuk membuka pesan di Pesan Tersimpan. Label bisa dilepas dengan menekan dan menahan pesan, pilih “Label”.",
  "it": "Tocca un messaggio per aprirlo in Messaggi salvati. Per togliere un'etichetta, tieni premuto il messaggio e scegli «Etichette».",
  "ko": "탭하면 저장한 메시지에서 해당 메시지가 열립니다. 라벨을 제거하려면 메시지를 길게 누르고 ‘라벨’을 선택하세요.",
  "ms": "Tekan untuk membuka mesej dalam Mesej Disimpan. Label boleh dibuang dengan tekan lama pada mesej, pilih “Label”.",
  "nl": "Tik om het bericht te openen in Bewaarde berichten. Een label verwijder je door lang op het bericht te drukken, onderdeel “Labels”.",
  "pl": "Stuknięcie otwiera wiadomość w Zapisanych wiadomościach. Etykietę zdejmiesz, przytrzymując wiadomość, pozycja „Etykiety”.",
  "pt": "Toque para abrir a mensagem nas Mensagens Salvas. Para remover uma etiqueta, toque e segure a mensagem e escolha “Etiquetas”.",
  "tr": "Mesajı Kayıtlı Mesajlar'da açmak için dokunun. Etiketi kaldırmak için mesaja basılı tutun ve “Etiketler” seçeneğini seçin.",
  "uk": "Натискання відкриває повідомлення в Збереженому. Зняти мітку можна довгим натисканням на повідомлення, пункт «Мітки».",
  "uz": "Xabarni “Saqlangan xabarlar”da ochish uchun bosing. Yorliqni olib tashlash uchun xabarni bosib turing va “Yorliqlar” bandini tanlang."
 },
 "Нажмите плюс вверху, чтобы добавить дело на этот день.": {
  "ar": "اضغط على + في الأعلى لإضافة مهمة لهذا اليوم.",
  "be": "Націсніце плюс уверсе, каб дадаць справу на гэты дзень.",
  "ca": "Toqueu el + de dalt per a afegir una tasca en aquest dia.",
  "de": "Tippe oben auf Plus, um eine Aufgabe für diesen Tag hinzuzufügen.",
  "en": "Tap plus at the top to add a task for this day.",
  "es": "Toca el + de arriba para añadir una tarea en este día.",
  "fa": "برای افزودن کار به این روز، روی + در بالا بزنید.",
  "fr": "Touchez le plus en haut pour ajouter une tâche à ce jour.",
  "id": "Ketuk plus di atas untuk menambahkan tugas pada tanggal ini.",
  "it": "Tocca + in alto per aggiungere un'attività a questo giorno.",
  "ko": "위의 +를 탭해 이날의 할 일을 추가하세요.",
  "ms": "Tekan tanda tambah di atas untuk menambah tugasan pada tarikh ini.",
  "nl": "Tik bovenaan op plus om een taak voor deze dag toe te voegen.",
  "pl": "Stuknij plus u góry, aby dodać zadanie na ten dzień.",
  "pt": "Toque no sinal de mais no topo para adicionar uma tarefa para este dia.",
  "tr": "Bu güne görev eklemek için üstteki artıya dokunun.",
  "uk": "Натисніть плюс угорі, щоб додати справу на цей день.",
  "uz": "Shu kunga vazifa qoʻshish uchun yuqoridagi plyusni bosing."
 },
 "Найдено {}. Личный чат и общие группы, нажатие открывает сообщение.": {
  "ar": "تم العثور على {}. المحادثة الخاصة والمجموعات المشتركة، اضغط لفتح الرسالة.",
  "be": "Знойдзена {}. Асабісты чат і агульныя групы, націск адкрывае паведамленне.",
  "ca": "Trobats {}. Xat privat i grups en comú, toqueu per a obrir el missatge.",
  "de": "{} gefunden. Privater Chat und gemeinsame Gruppen, tippe, um die Nachricht zu öffnen.",
  "en": "Found {}. Private chat and common groups, tap to open a message.",
  "es": "Encontrados {}. Chat privado y grupos en común, toca para abrir el mensaje.",
  "fa": "{} مورد پیدا شد. گفتگوی خصوصی و گروه‌های مشترک، با زدن روی هر مورد پیام باز می‌شود.",
  "fr": "{} résultat(s). Discussion privée et groupes communs, touchez pour ouvrir le message.",
  "id": "Ditemukan {}. Obrolan pribadi dan grup yang sama, ketuk untuk membuka pesan.",
  "it": "Trovati {}. Chat privata e gruppi in comune, tocca per aprire il messaggio.",
  "ko": "{}개 찾음. 개인 대화와 공통 그룹이며, 탭하면 메시지가 열립니다.",
