 "Отмеченные метки видны под именем «{}» в списке чатов. Цвет и название меняются в Dkx, раздел «Метки».": {
  "ar": "تظهر الوسوم المحددة تحت اسم «{}» في قائمة المحادثات. يُغيَّر اللون والاسم في Dkx، قسم «الوسوم».",
  "be": "Адзначаныя меткі відаць пад назвай «{}» у спісе чатаў. Колер і назва мяняюцца ў Dkx, раздзел «Меткі».",
  "ca": "Les etiquetes marcades es veuen sota «{}» a la llista de xats. El color i el nom es canvien a Dkx, secció «Etiquetes».",
  "de": "Ausgewählte Labels erscheinen in der Chatliste unter „{}“. Farbe und Namen änderst du in Dkx, Bereich „Labels“.",
  "en": "Checked labels appear under “{}” in the chat list. Color and name can be changed in Dkx, “Labels” section.",
  "es": "Las etiquetas marcadas se ven bajo «{}» en la lista de chats. El color y el nombre se cambian en Dkx, sección «Etiquetas».",
  "fa": "برچسب‌های علامت‌خورده زیر نام «{}» در فهرست گفتگوها دیده می‌شوند. رنگ و نام در Dkx، بخش «برچسب‌ها» تغییر می‌کند.",
  "fr": "Les étiquettes cochées apparaissent sous « {} » dans la liste des discussions. La couleur et le nom se modifient dans Dkx, section « Étiquettes ».",
  "id": "Label yang dicentang terlihat di bawah nama “{}” di daftar obrolan. Warna dan nama diubah di Dkx, bagian “Label”.",
  "it": "Le etichette selezionate compaiono sotto «{}» nell'elenco delle chat. Colore e nome si cambiano in Dkx, sezione «Etichette».",
  "ko": "선택한 라벨은 대화 목록에서 ‘{}’ 이름 아래에 표시됩니다. 색상과 이름은 Dkx의 ‘라벨’ 섹션에서 바꿀 수 있습니다.",
  "ms": "Label yang ditanda kelihatan di bawah nama “{}” dalam senarai bual. Warna dan nama ditukar dalam Dkx, bahagian “Label”.",
  "nl": "Aangevinkte labels staan in de chatlijst onder “{}”. Kleur en naam wijzig je in Dkx, onderdeel “Labels”.",
  "pl": "Zaznaczone etykiety widać pod nazwą „{}” na liście czatów. Kolor i nazwę zmienisz w Dkx, sekcja „Etykiety”.",
  "pt": "As etiquetas marcadas aparecem abaixo do nome “{}” na lista de chats. A cor e o nome são alterados no Dkx, seção “Etiquetas”.",
  "tr": "İşaretli etiketler sohbet listesinde “{}” adının altında görünür. Renk ve ad, Dkx ayarlarındaki “Etiketler” bölümünde değiştirilir.",
  "uk": "Позначені мітки видно під назвою «{}» у списку чатів. Колір і назва змінюються в Dkx, розділ «Мітки».",
  "uz": "Belgilangan yorliqlar chatlar roʻyxatida “{}” nomi ostida koʻrinadi. Rangi va nomi Dkx ichidagi “Yorliqlar” boʻlimida oʻzgartiriladi."
 },
 "Отмеченные метки стоят на всех выбранных сообщениях. Нажатие ставит метку всем или снимает со всех.": {
  "ar": "الوسوم المحددة موجودة على كل الرسائل المختارة. الضغط يضيف الوسم إليها جميعًا أو يزيله منها جميعًا.",
  "be": "Адзначаныя меткі стаяць на ўсіх выбраных паведамленнях. Націск ставіць метку ўсім або здымае з усіх.",
  "ca": "Les etiquetes marcades són a tots els missatges seleccionats. En tocar-ne una, s'aplica a tots o es treu de tots.",
  "de": "Abgehakte Labels sind bei allen ausgewählten Nachrichten gesetzt. Tippen setzt das Label bei allen oder entfernt es bei allen.",
  "en": "Checked labels are on all selected messages. Tapping adds the label to all of them or removes it from all.",
  "es": "Las etiquetas marcadas están en todos los mensajes seleccionados. Al tocar una, se pone en todos o se quita de todos.",
  "fa": "برچسب‌های علامت‌خورده روی همه پیام‌های انتخاب‌شده هستند. زدن روی برچسب، آن را روی همه می‌گذارد یا از همه برمی‌دارد.",
  "fr": "Les étiquettes cochées sont sur tous les messages sélectionnés. Toucher une étiquette l'ajoute à tous ou la retire de tous.",
  "id": "Label yang dicentang terpasang di semua pesan yang dipilih. Ketuk untuk memasang label di semuanya atau melepasnya dari semuanya.",
  "it": "Le etichette spuntate sono su tutti i messaggi selezionati. Toccandone una, la metti su tutti o la togli da tutti.",
  "ko": "체크된 라벨은 선택한 모든 메시지에 붙어 있습니다. 탭하면 모두에 라벨을 붙이거나 모두에서 제거합니다.",
  "ms": "Label yang ditanda ada pada semua mesej yang dipilih. Tekan untuk memasang label pada semua atau membuangnya daripada semua.",
  "nl": "Aangevinkte labels staan op alle geselecteerde berichten. Tikken zet het label op allemaal of haalt het van allemaal weg.",
  "pl": "Zaznaczone etykiety są na wszystkich wybranych wiadomościach. Stuknięcie dodaje etykietę wszystkim albo zdejmuje ją ze wszystkich.",
  "pt": "As etiquetas marcadas estão em todas as mensagens selecionadas. Tocar coloca a etiqueta em todas ou tira de todas.",
  "tr": "İşaretli etiketler tüm seçili mesajlarda var. Dokunmak etiketi hepsine ekler veya hepsinden kaldırır.",
  "uk": "Позначені мітки стоять на всіх вибраних повідомленнях. Натискання ставить мітку всім або знімає з усіх.",
  "uz": "Belgilangan yorliqlar barcha tanlangan xabarlarda bor. Bossangiz, yorliq hammasiga qoʻyiladi yoki hammasidan olib tashlanadi."
 },
 "Отмеченные метки стоят на всех выбранных чатах. Нажатие ставит метку всем или снимает со всех.": {
  "ar": "الوسوم المحددة موجودة على كل المحادثات المختارة. الضغط يضيف الوسم إليها جميعًا أو يزيله منها جميعًا.",
  "be": "Адзначаныя меткі стаяць на ўсіх выбраных чатах. Націск ставіць метку ўсім або здымае з усіх.",
  "ca": "Les etiquetes marcades són a tots els xats seleccionats. En tocar-ne una, s'aplica a tots o es treu de tots.",
  "de": "Abgehakte Labels sind bei allen ausgewählten Chats gesetzt. Tippen setzt das Label bei allen oder entfernt es bei allen.",
  "en": "Checked labels are on all selected chats. Tapping adds the label to all of them or removes it from all.",
  "es": "Las etiquetas marcadas están en todos los chats seleccionados. Al tocar una, se pone en todos o se quita de todos.",
  "fa": "برچسب‌های علامت‌خورده روی همه گفتگوهای انتخاب‌شده هستند. زدن روی برچسب، آن را روی همه می‌گذارد یا از همه برمی‌دارد.",
  "fr": "Les étiquettes cochées sont sur toutes les discussions sélectionnées. Toucher une étiquette l'ajoute à toutes ou la retire de toutes.",
  "id": "Label yang dicentang terpasang di semua obrolan yang dipilih. Ketuk untuk memasang label di semuanya atau melepasnya dari semuanya.",
  "it": "Le etichette spuntate sono su tutte le chat selezionate. Toccandone una, la metti su tutte o la togli da tutte.",
  "ko": "체크된 라벨은 선택한 모든 대화에 붙어 있습니다. 탭하면 모두에 라벨을 붙이거나 모두에서 제거합니다.",
  "ms": "Label yang ditanda ada pada semua bual yang dipilih. Tekan untuk memasang label pada semua atau membuangnya daripada semua.",
  "nl": "Aangevinkte labels staan op alle geselecteerde chats. Tikken zet het label op allemaal of haalt het van allemaal weg.",
  "pl": "Zaznaczone etykiety są na wszystkich wybranych czatach. Stuknięcie dodaje etykietę wszystkim albo zdejmuje ją ze wszystkich.",
  "pt": "As etiquetas marcadas estão em todos os chats selecionados. Tocar coloca a etiqueta em todos ou tira de todos.",
  "tr": "İşaretli etiketler tüm seçili sohbetlerde var. Dokunmak etiketi hepsine ekler veya hepsinden kaldırır.",
  "uk": "Позначені мітки стоять на всіх вибраних чатах. Натискання ставить мітку всім або знімає з усіх.",
  "uz": "Belgilangan yorliqlar barcha tanlangan chatlarda bor. Bossangiz, yorliq hammasiga qoʻyiladi yoki hammasidan olib tashlanadi."
 },
