 "Повторно загрузить в Google Drive": {
  "ar": "إعادة الرفع إلى Google Drive",
  "be": "Паўторна запампаваць у Google Drive",
  "ca": "Torna a pujar a Google Drive",
  "de": "Erneut in Google Drive speichern",
  "en": "Upload to Google Drive again",
  "es": "Volver a subir a Google Drive",
  "fa": "بارگذاری دوباره در Google Drive",
  "fr": "Enregistrer à nouveau sur Google Drive",
  "id": "Unggah ulang ke Google Drive",
  "it": "Carica di nuovo su Google Drive",
  "ko": "Google Drive에 다시 업로드",
  "ms": "Muat naik semula ke Google Drive",
  "nl": "Opnieuw opslaan in Google Drive",
  "pl": "Prześlij ponownie na Google Drive",
  "pt": "Enviar de novo para o Google Drive",
  "tr": "Google Drive'a tekrar yükle",
  "uk": "Повторно завантажити в Google Drive",
  "uz": "Google Drivega qayta yuklash"
 },
 "Подмена настраивается прямо на карте, в экране отправки геопозиции. Там переключатель Настоящая, Точка или Маршрут, точки ставятся долгим нажатием на карту. Трансляция сама запускает движение по маршруту.\n\nДействует на трансляцию, отправку местоположения и запросы ботов. На системные карты и другие приложения не влияет.": {
  "ar": "يُضبط استبدال الموقع مباشرة على الخريطة، في شاشة إرسال الموقع. هناك مبدّل حقيقي أو نقطة أو مسار، وتوضع النقاط بالضغط المطوّل على الخريطة. تبدأ مشاركة الموقع الحي الحركة على المسار تلقائيًا.\n\nيسري على الموقع الحي وإرسال الموقع وطلبات البوتات. لا يؤثر على خرائط النظام ولا على التطبيقات الأخرى.",
  "be": "Падмена наладжваецца проста на карце, на экране адпраўкі геапазіцыі. Там пераключальнік Сапраўдная, Кропка або Маршрут, кропкі ставяцца доўгім націскам на карту. Трансляцыя сама запускае рух па маршруце.\n\nДзейнічае на трансляцыю, адпраўку месцазнаходжання і запыты ботаў. На сістэмныя карты і іншыя праграмы не ўплывае.",
  "ca": "La simulació es configura directament al mapa, a la pantalla d'enviament de la ubicació. Allà hi ha el selector Real, Punt o Ruta, i els punts es posen mantenint premut el mapa. La ubicació en directe inicia sola el moviment per la ruta.\n\nAfecta la ubicació en directe, l'enviament de la ubicació i les sol·licituds dels bots. No afecta els mapes del sistema ni altres aplicacions.",
  "de": "Die Simulation stellst du direkt auf der Karte ein, im Bildschirm zum Senden des Standorts. Dort gibt es den Umschalter Echt, Punkt oder Route, Punkte setzt du durch langes Drücken auf die Karte. Der Live-Standort startet die Bewegung entlang der Route von selbst.\n\nGilt für den Live-Standort, das Senden des Standorts und Anfragen von Bots. Auf Systemkarten und andere Apps wirkt es sich nicht aus.",
  "en": "The override is set up right on the map, on the location sending screen. There is a Real, Point or Route switch, points are placed by long-pressing the map. Live location starts moving along the route by itself.\n\nApplies to live location, sending location and bot requests. Doesn't affect system maps or other apps.",
  "es": "La simulación se configura directamente en el mapa, en la pantalla de envío de ubicación. Ahí hay un selector Real, Punto o Ruta, y los puntos se ponen manteniendo pulsado el mapa. La ubicación en tiempo real inicia sola el movimiento por la ruta.\n\nAfecta a la ubicación en tiempo real, al envío de ubicación y a las solicitudes de bots. No afecta a los mapas del sistema ni a otras apps.",
  "fa": "جایگزینی موقعیت مستقیماً روی نقشه، در صفحه ارسال موقعیت مکانی تنظیم می‌شود. آنجا کلید واقعی، نقطه یا مسیر هست و نقطه‌ها با لمس طولانی روی نقشه گذاشته می‌شوند. موقعیت مکانی لحظه‌ای خودش حرکت روی مسیر را شروع می‌کند.\n\nروی موقعیت مکانی لحظه‌ای، ارسال موقعیت و درخواست‌های ربات‌ها اثر دارد. روی نقشه‌های سیستم و برنامه‌های دیگر اثری ندارد.",
  "fr": "La simulation se règle directement sur la carte, dans l'écran d'envoi de position. Il y a un sélecteur Réelle, Point ou Itinéraire, les points se placent par un appui long sur la carte. La position en direct lance d'elle-même le trajet le long de l'itinéraire.\n\nS'applique à la position en direct, à l'envoi de position et aux requêtes des bots. N'affecte pas les cartes du système ni les autres apps.",
  "id": "Lokasi palsu diatur langsung di peta, di layar pengiriman lokasi. Di sana ada pilihan Asli, Titik, atau Rute, dan titik ditaruh dengan menekan dan menahan peta. Live Location otomatis memulai pergerakan di sepanjang rute.\n\nBerlaku untuk Live Location, pengiriman lokasi, dan permintaan bot. Tidak memengaruhi peta sistem dan aplikasi lain.",
  "it": "La simulazione si imposta direttamente sulla mappa, nella schermata di invio della posizione. Lì c'è il selettore Reale, Punto o Percorso, e i punti si mettono tenendo premuto sulla mappa. La posizione in tempo reale avvia da sola il movimento lungo il percorso.\n\nVale per la posizione in tempo reale, l'invio della posizione e le richieste dei bot. Non influisce sulle mappe di sistema né sulle altre app.",
  "ko": "위치 대체는 위치 보내기 화면의 지도에서 바로 설정합니다. 그곳에 실제, 지점, 경로 전환 버튼이 있으며, 지도를 길게 눌러 지점을 지정합니다. 실시간 위치 공유를 시작하면 경로를 따라 이동이 자동으로 시작됩니다.\n\n실시간 위치, 위치 보내기, 봇 요청에 적용됩니다. 시스템 지도와 다른 앱에는 영향을 주지 않습니다.",
  "ms": "Lokasi palsu ditetapkan terus pada peta, di skrin penghantaran lokasi. Di situ ada pilihan Sebenar, Titik atau Laluan, dan titik diletakkan dengan tekan lama pada peta. Lokasi Langsung sendiri memulakan pergerakan di sepanjang laluan.\n\nBerkuat kuasa untuk Lokasi Langsung, penghantaran lokasi dan permintaan bot. Tidak menjejaskan peta sistem dan aplikasi lain.",
  "nl": "De simulatie stel je direct op de kaart in, op het scherm voor het versturen van een locatie. Daar staat de schakelaar Echt, Punt of Route, punten zet je door lang op de kaart te drukken. De live locatie start de beweging langs de route vanzelf.\n\nGeldt voor de live locatie, het versturen van een locatie en verzoeken van bots. Heeft geen invloed op systeemkaarten en andere apps.",
  "pl": "Podmianę ustawia się bezpośrednio na mapie, na ekranie wysyłania lokalizacji. Jest tam przełącznik Prawdziwa, Punkt lub Trasa, punkty stawia się przytrzymaniem mapy. Udostępnianie na żywo samo uruchamia ruch po trasie.\n\nDziała na udostępnianie na żywo, wysyłanie lokalizacji i zapytania botów. Nie wpływa na mapy systemowe ani inne aplikacje.",
  "pt": "A localização falsa é configurada direto no mapa, na tela de envio de localização. Lá há a opção Real, Ponto ou Rota, e os pontos são marcados ao tocar e segurar no mapa. A localização ao vivo inicia sozinha o movimento pela rota.\n\nVale para a localização ao vivo, o envio de localização e as solicitações de bots. Não afeta os mapas do sistema nem outros apps.",
  "tr": "Konum değiştirme doğrudan haritada, konum gönderme ekranında ayarlanır. Orada Gerçek, Nokta veya Rota seçici bulunur, noktalar haritaya basılı tutarak konur. Canlı konum rota boyunca hareketi kendisi başlatır.\n\nCanlı konuma, konum göndermeye ve bot isteklerine etki eder. Sistem haritalarını ve diğer uygulamaları etkilemez.",
  "uk": "Підміна налаштовується просто на карті, на екрані надсилання геопозиції. Там перемикач Справжня, Точка або Маршрут, точки ставляться довгим натисканням на карту. Трансляція сама запускає рух маршрутом.\n\nДіє на трансляцію, надсилання місцезнаходження і запити ботів. На системні карти й інші застосунки не впливає.",
  "uz": "Joylashuvni almashtirish bevosita xaritada, joylashuv yuborish ekranida sozlanadi. U yerda Haqiqiy, Nuqta yoki Yoʻnalish almashtirgichi bor, nuqtalar xaritani bosib turib qoʻyiladi. Jonli joylashuv yoʻnalish boʻylab harakatni oʻzi boshlaydi.\n\nJonli joylashuv, joylashuv yuborish va botlar soʻrovlariga taʼsir qiladi. Tizim xaritalari va boshqa ilovalarga taʼsir qilmaydi."
 },
