 "Поиск идёт на сервере Telegram, поэтому находится и то, что не загружено на телефон. Перед выгрузкой покажу, сколько нашлось. Файлы грузятся фоном, ход виден в полосе вверху экрана, повторы на диск не попадут. За один раз до {} файлов.": {
  "ar": "يجري البحث على خادم Telegram، لذا يُعثر أيضًا على ما لم يُنزَّل على الهاتف. قبل الرفع سأعرض عدد ما وُجد. تُرفع الملفات في الخلفية، ويظهر التقدم في الشريط أعلى الشاشة، ولن تُرفع الملفات المكررة. حتى {} ملف في المرة الواحدة.",
  "be": "Пошук ідзе на серверы Telegram, таму знаходзіцца і тое, што не спампавана на тэлефон. Перад выгрузкай пакажу, колькі знайшлося. Файлы запампоўваюцца ў фоне, ход відаць у паласе ўверсе экрана, паўторы на дыск не трапяць. За адзін раз да {} файлаў.",
  "ca": "La cerca es fa al servidor de Telegram, per això també troba el que no està baixat al telèfon. Abans de pujar-los us mostraré quants se n'han trobat. Els fitxers es pugen en segon pla, el progrés es veu a la barra de dalt de la pantalla i els duplicats no es pujaran. Fins a {} fitxers per tanda.",
  "de": "Die Suche läuft auf dem Telegram-Server, daher wird auch gefunden, was nicht auf das Telefon geladen ist. Vor dem Hochladen siehst du, wie viel gefunden wurde. Die Dateien werden im Hintergrund hochgeladen, der Fortschritt ist in der Leiste oben auf dem Bildschirm zu sehen, Duplikate landen nicht auf Drive. Pro Durchgang bis zu {} Dateien.",
  "en": "The search runs on Telegram's server, so it also finds files not downloaded to the phone. Before uploading you'll see how many were found. Files upload in the background, progress is shown in the bar at the top of the screen, duplicates won't be uploaded. Up to {} files at a time.",
  "es": "La búsqueda se hace en el servidor de Telegram, así que también encuentra lo que no está descargado en el teléfono. Antes de subir te mostraré cuánto se encontró. Los archivos se suben en segundo plano, el progreso se ve en la barra de arriba de la pantalla y los duplicados no se subirán. Hasta {} archivos por tanda.",
  "fa": "جستجو روی سرور Telegram انجام می‌شود، پس مواردی هم که روی گوشی دانلود نشده‌اند پیدا می‌شوند. پیش از بارگذاری نشان می‌دهم چند مورد پیدا شد. فایل‌ها در پس‌زمینه بارگذاری می‌شوند، پیشرفت در نوار بالای صفحه دیده می‌شود و موارد تکراری بارگذاری نمی‌شوند. هر بار تا {} فایل.",
  "fr": "La recherche se fait sur le serveur Telegram, elle trouve donc aussi ce qui n'est pas téléchargé sur le téléphone. Avant l'envoi, vous verrez combien d'éléments ont été trouvés. Les fichiers sont envoyés en arrière-plan, la progression s'affiche dans la barre en haut de l'écran, les doublons ne seront pas envoyés sur le Drive. Jusqu'à {} fichiers par envoi.",
  "id": "Pencarian dilakukan di server Telegram, jadi berkas yang belum diunduh ke ponsel juga ditemukan. Sebelum mengunggah, saya tunjukkan berapa yang ditemukan. Berkas diunggah di latar belakang, progresnya terlihat di bilah atas layar, duplikat tidak akan masuk ke Drive. Maksimal {} berkas sekali jalan.",
  "it": "La ricerca avviene sul server di Telegram, quindi trova anche ciò che non è scaricato sul telefono. Prima del caricamento ti mostrerò quanto è stato trovato. I file vengono caricati in background, l'avanzamento si vede nella barra in alto sullo schermo e i duplicati non verranno caricati. Fino a {} file per volta.",
  "ko": "검색은 Telegram 서버에서 이루어지므로 휴대폰에 다운로드되지 않은 파일도 찾습니다. 업로드 전에 찾은 개수를 보여 드립니다. 파일은 백그라운드에서 업로드되고 진행 상황은 화면 위쪽 막대에 표시되며, 중복 파일은 업로드되지 않습니다. 한 번에 최대 {}개 파일.",
  "ms": "Carian dibuat di pelayan Telegram, jadi fail yang belum dimuat turun ke telefon juga ditemui. Sebelum memuat naik, saya tunjukkan berapa yang ditemui. Fail dimuat naik di latar belakang, kemajuannya kelihatan pada bar di atas skrin, fail pendua tidak akan masuk ke Drive. Maksimum {} fail sekali jalan.",
  "nl": "Er wordt gezocht op de Telegram-server, dus wordt ook gevonden wat niet op de telefoon is gedownload. Voor het uploaden zie je hoeveel er is gevonden. Bestanden worden op de achtergrond geüpload, de voortgang zie je in de balk bovenaan het scherm, dubbele bestanden komen niet op de drive. Maximaal {} bestanden per keer.",
  "pl": "Wyszukiwanie odbywa się na serwerze Telegram, więc znajduje też to, czego nie pobrano na telefon. Przed przesłaniem pokażę, ile znaleziono. Pliki przesyłają się w tle, postęp widać na pasku u góry ekranu, duplikaty nie trafią na dysk. Za jednym razem do {} plików.",
  "pt": "A busca é feita no servidor do Telegram, por isso encontra também o que não foi baixado no celular. Antes de enviar, mostro quantos foram encontrados. Os arquivos são enviados em segundo plano, o progresso aparece na barra no topo da tela, e duplicados não vão para o Drive. Até {} arquivos por vez.",
  "tr": "Arama Telegram sunucusunda yapılır, bu yüzden telefona indirilmemiş dosyalar da bulunur. Yüklemeden önce kaç tane bulunduğunu göstereceğim. Dosyalar arka planda yüklenir, ilerleme ekranın üstündeki çubukta görünür, tekrarlar diske gitmez. Tek seferde en fazla {} dosya.",
  "uk": "Пошук іде на сервері Telegram, тому знаходиться й те, що не завантажено на телефон. Перед вивантаженням покажу, скільки знайшлося. Файли завантажуються у фоні, перебіг видно в смузі вгорі екрана, повтори на диск не потраплять. За один раз до {} файлів.",
  "uz": "Qidiruv Telegram serverida boʻladi, shuning uchun telefonga yuklab olinmagan fayllar ham topiladi. Yuklashdan oldin qancha topilganini koʻrsataman. Fayllar fonda yuklanadi, jarayon ekran yuqorisidagi chiziqda koʻrinadi, takrorlar diskka tushmaydi. Bir safarda {} tagacha fayl."
 },
