 "Прячет штатные теги Telegram в Избранном. Пропадёт ряд тегов при поиске и ряд тегов в меню долгого нажатия на сообщение. Свои метки Dkx в Избранном работают отдельно и остаются.": {
  "ar": "يُخفي علامات Telegram المدمجة في الرسائل المحفوظة. سيختفي صف العلامات عند البحث وصف العلامات في قائمة الضغط المطوّل على الرسالة. وسوم Dkx في الرسائل المحفوظة تعمل بشكل منفصل وتبقى كما هي.",
  "be": "Хавае ўбудаваныя тэгі Telegram у Захаваным. Знікнуць радок тэгаў пры пошуку і радок тэгаў у меню доўгага націску на паведамленне. Уласныя меткі Dkx у Захаваным працуюць асобна і застаюцца.",
  "ca": "Amaga les etiquetes integrades de Telegram a Missatges desats. Desapareixen la fila d'etiquetes de la cerca i la del menú que s'obre en mantenir premut un missatge. Les etiquetes pròpies de Dkx a Missatges desats funcionen a part i es conserven.",
  "de": "Blendet die Telegram-eigenen Tags in den Gespeicherten Nachrichten aus. Die Tag-Leiste in der Suche und die Tag-Leiste im Menü bei langem Drücken auf eine Nachricht verschwinden. Die Dkx-Labels in den Gespeicherten Nachrichten funktionieren unabhängig davon und bleiben erhalten.",
  "en": "Hides Telegram’s own tags in Saved Messages. The tag row in search and the tag row in the message long-press menu disappear. Dkx labels in Saved Messages work separately and stay.",
  "es": "Oculta las etiquetas nativas de Telegram en Mensajes guardados. Desaparecen la fila de etiquetas en la búsqueda y la del menú que se abre al mantener pulsado un mensaje. Las etiquetas propias de Dkx en Mensajes guardados funcionan aparte y se conservan.",
  "fa": "تگ‌های خود Telegram را در پیام‌های ذخیره شده پنهان می‌کند. ردیف تگ‌ها هنگام جستجو و ردیف تگ‌ها در منوی لمس طولانی روی پیام از بین می‌روند. برچسب‌های Dkx در پیام‌های ذخیره شده جداگانه کار می‌کنند و باقی می‌مانند.",
  "fr": "Masque les tags propres à Telegram dans Messages enregistrés. La barre de tags dans la recherche et celle du menu d'appui long sur un message disparaissent. Les étiquettes Dkx dans Messages enregistrés fonctionnent à part et restent.",
  "id": "Menyembunyikan tag bawaan Telegram di Pesan Tersimpan. Baris tag saat mencari dan baris tag di menu tekan dan tahan pesan akan hilang. Label Dkx di Pesan Tersimpan bekerja terpisah dan tetap ada.",
  "it": "Nasconde i tag integrati di Telegram in Messaggi salvati. Spariscono la riga dei tag nella ricerca e quella nel menu che si apre tenendo premuto un messaggio. Le etichette di Dkx in Messaggi salvati funzionano a parte e restano.",
  "ko": "저장한 메시지에서 Telegram 기본 태그를 숨깁니다. 검색할 때 나오는 태그 줄과 메시지를 길게 누르면 나오는 메뉴의 태그 줄이 사라집니다. 저장한 메시지의 Dkx 라벨은 별도로 작동하며 그대로 남습니다.",
  "ms": "Menyembunyikan tag terbina dalam Telegram dalam Mesej Disimpan. Baris tag semasa carian dan baris tag dalam menu tekan lama pada mesej akan hilang. Label Dkx dalam Mesej Disimpan berfungsi berasingan dan kekal.",
  "nl": "Verbergt de eigen tags van Telegram in Bewaarde berichten. De rij tags bij het zoeken en de rij tags in het menu bij lang drukken op een bericht verdwijnen. De Dkx-labels in Bewaarde berichten werken daar los van en blijven staan.",
  "pl": "Ukrywa wbudowane tagi Telegram w Zapisanych wiadomościach. Zniknie wiersz tagów podczas wyszukiwania i wiersz tagów w menu przytrzymania wiadomości. Własne etykiety Dkx w Zapisanych wiadomościach działają osobno i zostają.",
  "pt": "Oculta as tags do próprio Telegram nas Mensagens Salvas. Somem a linha de tags na busca e a linha de tags no menu ao tocar e segurar uma mensagem. As etiquetas do Dkx nas Mensagens Salvas funcionam à parte e continuam.",
  "tr": "Telegram'ın Kayıtlı Mesajlar'daki kendi etiketlerini gizler. Aramadaki etiket satırı ve mesaja basılı tutunca açılan menüdeki etiket satırı kaybolur. Kayıtlı Mesajlar'daki Dkx etiketleri ayrı çalışır ve yerinde kalır.",
  "uk": "Ховає вбудовані теги Telegram у Збереженому. Зникнуть рядок тегів під час пошуку й рядок тегів у меню довгого натискання на повідомлення. Власні мітки Dkx у Збереженому працюють окремо й лишаються.",
  "uz": "Telegramning “Saqlangan xabarlar”dagi oʻz teglarini berkitadi. Qidiruvdagi teglar qatori va xabarni bosib turganda chiqadigan menyudagi teglar qatori yoʻqoladi. “Saqlangan xabarlar”dagi Dkx yorliqlari alohida ishlaydi va saqlanib qoladi."
 },
 "Пункт «В Google Drive» в меню медиа. Файлы уходят только на ваш диск, в папку Dkx.": {
  "ar": "بند «حفظ في Google Drive» في قائمة الوسائط. تذهب الملفات إلى حسابك في Google Drive فقط، في مجلد Dkx.",
  "be": "Пункт «У Google Drive» у меню медыя. Файлы ідуць толькі на ваш дыск, у папку Dkx.",
  "ca": "L'opció «Puja a Google Drive» al menú del contingut multimèdia. Els fitxers només van al vostre Drive, a la carpeta Dkx.",
  "de": "Der Punkt „In Google Drive speichern“ im Medienmenü. Dateien gehen nur auf dein Drive, in den Ordner Dkx.",
  "en": "The “Save to Google Drive” item in the media menu. Files go only to your drive, into the Dkx folder.",
  "es": "La opción «Subir a Google Drive» en el menú de multimedia. Los archivos van solo a tu Drive, a la carpeta Dkx.",
  "fa": "گزینه «ذخیره در Google Drive» در منوی رسانه. فایل‌ها فقط به Google Drive شما، در پوشه Dkx می‌روند.",
  "fr": "L'option « Enregistrer sur Google Drive » dans le menu des médias. Les fichiers vont uniquement sur votre Drive, dans le dossier Dkx.",
  "id": "Item “Simpan ke Google Drive” di menu media. Berkas hanya masuk ke Drive Anda, ke folder Dkx.",
  "it": "La voce «Carica su Google Drive» nel menu dei media. I file vanno solo sul tuo Drive, nella cartella Dkx.",
  "ko": "미디어 메뉴의 ‘Google Drive에 저장’ 항목입니다. 파일은 내 Google Drive의 Dkx 폴더에만 저장됩니다.",
  "ms": "Item “Simpan ke Google Drive” dalam menu media. Fail hanya pergi ke Drive anda, ke folder Dkx.",
  "nl": "Het onderdeel “Opslaan in Google Drive” in het mediamenu. Bestanden gaan alleen naar je eigen drive, in de map Dkx.",
  "pl": "Pozycja „Zapisz na Google Drive” w menu multimediów. Pliki trafiają tylko na twój dysk, do folderu Dkx.",
  "pt": "O item “Salvar no Google Drive” no menu de mídia. Os arquivos vão só para o seu Drive, na pasta Dkx.",
  "tr": "Medya menüsünde “Google Drive'a” seçeneği. Dosyalar yalnızca sizin diskinize, Dkx klasörüne gider.",
  "uk": "Пункт «У Google Drive» в меню медіа. Файли йдуть лише на ваш диск, у теку Dkx.",
  "uz": "Media menyusidagi “Google Drivega” bandi. Fayllar faqat sizning diskingizga, Dkx jildiga yuboriladi."
 },
