 "Сами экраны не пропадают. Контакты открываются из списка чатов при создании чата, звонки из «Недавних звонков» в настройках, если эта строка не спрятана.": {
  "ar": "الشاشات نفسها لا تختفي. تُفتح جهات الاتصال من قائمة المحادثات عند إنشاء محادثة، والمكالمات من «أحدث المكالمات» في الإعدادات، إن لم يكن هذا الصف مخفيًا.",
  "be": "Самі экраны не знікаюць. Кантакты адкрываюцца са спісу чатаў пры стварэнні чата, званкі з «Нядаўніх званкоў» у наладах, калі гэты радок не схаваны.",
  "ca": "Les pantalles en si no desapareixen. Els contactes s'obren des de la llista de xats en crear un xat, i les trucades des de «Trucades recents» a la configuració, si aquesta fila no està amagada.",
  "de": "Die Bildschirme selbst bleiben erhalten. Kontakte öffnest du aus der Chatliste beim Erstellen eines Chats, Anrufe über „Letzte Anrufe“ in den Einstellungen, sofern diese Zeile nicht ausgeblendet ist.",
  "en": "The screens themselves stay available. Contacts open from the chat list when starting a new chat, calls from “Recent Calls” in settings, if that row isn't hidden.",
  "es": "Las pantallas en sí no desaparecen. Los contactos se abren desde la lista de chats al crear un chat, y las llamadas desde «Llamadas recientes» en ajustes, si esa fila no está oculta.",
  "fa": "خود صفحه‌ها از بین نمی‌روند. مخاطبین هنگام ساخت گفتگو از فهرست گفتگوها باز می‌شوند و تماس‌ها از «تماس‌های اخیر» در تنظیمات، اگر این ردیف پنهان نباشد.",
  "fr": "Les écrans eux-mêmes ne disparaissent pas. Les contacts s'ouvrent depuis la liste des discussions lors de la création d'une discussion, les appels depuis « Appels récents » dans les paramètres, si cette ligne n'est pas masquée.",
  "id": "Layarnya sendiri tidak hilang. Kontak dibuka dari daftar obrolan saat membuat obrolan baru, panggilan dari “Panggilan Terakhir” di pengaturan, jika baris itu tidak disembunyikan.",
  "it": "Le schermate in sé non spariscono. I contatti si aprono dall'elenco delle chat quando crei una chat, le chiamate da «Chiamate recenti» nelle impostazioni, se quella riga non è nascosta.",
  "ko": "화면 자체는 사라지지 않습니다. 연락처는 대화 목록에서 새 대화를 만들 때 열리고, 전화는 설정의 ‘최근 통화’에서 열립니다. 단, 그 행을 숨기지 않은 경우에 한합니다.",
  "ms": "Skrin itu sendiri tidak hilang. Kenalan dibuka dari senarai bual semasa memulakan bual baharu, panggilan dari “Panggilan Terbaru” dalam tetapan, jika baris itu tidak disembunyikan.",
  "nl": "De schermen zelf verdwijnen niet. Contacten open je vanuit de chatlijst als je een chat start, oproepen via “Recente oproepen” in de instellingen, als die rij niet verborgen is.",
  "pl": "Same ekrany nie znikają. Kontakty otwierają się z listy czatów przy tworzeniu czatu, połączenia z „Ostatnich połączeń” w ustawieniach, jeśli ten wiersz nie jest ukryty.",
  "pt": "As telas em si não somem. Os contatos abrem pela lista de chats ao criar um chat, e as chamadas por “Chamadas Recentes” nas configurações, se essa linha não estiver oculta.",
  "tr": "Ekranların kendisi kaybolmaz. Kişiler, sohbet listesinde yeni sohbet oluştururken açılır, aramalar ise ayarlardaki “Son Aramalar” satırından, bu satır gizli değilse.",
  "uk": "Самі екрани не зникають. Контакти відкриваються зі списку чатів під час створення чату, дзвінки з «Нещодавніх дзвінків» у налаштуваннях, якщо цей рядок не сховано.",
  "uz": "Ekranlarning oʻzi yoʻqolmaydi. Kontaktlar chatlar roʻyxatidan yangi chat yaratishda ochiladi, chaqiruvlar esa sozlamalardagi “Oxirgi chaqiruvlar”dan, agar bu qator berkitilmagan boʻlsa."
 },
