 "Снять метку можно долгим нажатием на чат, пункт «Метки».": {
  "ar": "لإزالة وسم، اضغط مطولًا على المحادثة واختر «الوسوم».",
  "be": "Зняць метку можна доўгім націскам на чат, пункт «Меткі».",
  "ca": "Per a treure una etiqueta, manteniu premut el xat i trieu «Etiquetes».",
  "de": "Ein Label entfernst du durch langes Drücken auf den Chat, Punkt „Labels“.",
  "en": "To remove a label, long-press the chat and choose “Labels”.",
  "es": "Para quitar una etiqueta, mantén pulsado el chat y elige «Etiquetas».",
  "fa": "برای برداشتن برچسب، روی گفتگو لمس طولانی کنید و «برچسب‌ها» را بزنید.",
  "fr": "Pour retirer une étiquette, faites un appui long sur la discussion, option « Étiquettes ».",
  "id": "Label bisa dilepas dengan menekan dan menahan obrolan, pilih “Label”.",
  "it": "Per togliere un'etichetta, tieni premuta la chat e scegli «Etichette».",
  "ko": "라벨을 제거하려면 대화를 길게 누르고 ‘라벨’을 선택하세요.",
  "ms": "Label boleh dibuang dengan tekan lama pada bual, pilih “Label”.",
  "nl": "Een label verwijder je door lang op de chat te drukken, onderdeel “Labels”.",
  "pl": "Etykietę zdejmiesz, przytrzymując czat, pozycja „Etykiety”.",
  "pt": "Para remover uma etiqueta, toque e segure o chat e escolha “Etiquetas”.",
  "tr": "Etiketi kaldırmak için sohbete basılı tutun ve “Etiketler” seçeneğini seçin.",
  "uk": "Зняти мітку можна довгим натисканням на чат, пункт «Мітки».",
  "uz": "Yorliqni olib tashlash uchun chatni bosib turing va “Yorliqlar” bandini tanlang."
 },
