 "Сообщений с этой меткой нет. Метка ставится долгим нажатием на сообщение в Избранном, пункт «Метки».": {
  "ar": "لا رسائل بهذا الوسم. يُضاف الوسم بالضغط المطوّل على رسالة في الرسائل المحفوظة واختيار «الوسوم».",
  "be": "Паведамленняў з гэтай меткай няма. Метка ставіцца доўгім націскам на паведамленне ў Захаваным, пункт «Меткі».",
  "ca": "No hi ha missatges amb aquesta etiqueta. Per a posar-la, manteniu premut un missatge a Missatges desats i trieu «Etiquetes».",
  "de": "Keine Nachrichten mit diesem Label. Ein Label setzt du durch langes Drücken auf eine Nachricht in den Gespeicherten Nachrichten, Punkt „Labels“.",
  "en": "No messages with this label. To add it, long-press a message in Saved Messages and choose “Labels”.",
  "es": "No hay mensajes con esta etiqueta. Para ponerla, mantén pulsado un mensaje en Mensajes guardados y elige «Etiquetas».",
  "fa": "پیامی با این برچسب نیست. برچسب با لمس طولانی روی پیام در پیام‌های ذخیره شده و گزینه «برچسب‌ها» گذاشته می‌شود.",
  "fr": "Aucun message avec cette étiquette. Pour l'ajouter, faites un appui long sur un message dans Messages enregistrés, option « Étiquettes ».",
  "id": "Tidak ada pesan dengan label ini. Label dipasang dengan menekan dan menahan pesan di Pesan Tersimpan, pilih “Label”.",
  "it": "Nessun messaggio con questa etichetta. Per aggiungerla, tieni premuto un messaggio in Messaggi salvati e scegli «Etichette».",
  "ko": "이 라벨이 붙은 메시지가 없습니다. 저장한 메시지에서 메시지를 길게 누르고 ‘라벨’을 선택하면 라벨을 붙일 수 있습니다.",
  "ms": "Tiada mesej dengan label ini. Label dipasang dengan tekan lama pada mesej dalam Mesej Disimpan, pilih “Label”.",
  "nl": "Geen berichten met dit label. Een label zet je door lang op een bericht in Bewaarde berichten te drukken, onderdeel “Labels”.",
  "pl": "Nie ma wiadomości z tą etykietą. Etykietę dodaje się przez przytrzymanie wiadomości w Zapisanych wiadomościach, pozycja „Etykiety”.",
  "pt": "Não há mensagens com esta etiqueta. Para colocá-la, toque e segure uma mensagem nas Mensagens Salvas e escolha “Etiquetas”.",
  "tr": "Bu etikete sahip mesaj yok. Etiket, Kayıtlı Mesajlar'daki bir mesaja basılı tutup “Etiketler” seçeneğiyle eklenir.",
  "uk": "Повідомлень із цією міткою немає. Мітка ставиться довгим натисканням на повідомлення в Збереженому, пункт «Мітки».",
  "uz": "Bu yorliqli xabarlar yoʻq. Yorliq “Saqlangan xabarlar”dagi xabarni bosib turib, “Yorliqlar” bandi orqali qoʻyiladi."
 },
