 "Список открывается долгим нажатием на вкладку «Чаты». В нём личные чаты, где последним написал собеседник, без ботов и архива. Сверху те, кто ждёт дольше всех.": {
  "ar": "تُفتح القائمة بالضغط المطوّل على علامة التبويب «المحادثات». تضم المحادثات الخاصة التي كان آخر من كتب فيها هو الطرف الآخر، دون البوتات والأرشيف. في الأعلى من ينتظر أطول مدة.",
  "be": "Спіс адкрываецца доўгім націскам на ўкладку «Чаты». У ім асабістыя чаты, дзе апошнім напісаў суразмоўца, без ботаў і архіва. Уверсе тыя, хто чакае даўжэй за ўсіх.",
  "ca": "La llista s'obre mantenint premuda la pestanya «Xats». Hi ha els xats privats en què l'últim missatge és de l'altra persona, sense bots ni arxiu. A dalt hi ha qui fa més temps que espera.",
  "de": "Die Liste öffnest du durch langes Drücken auf den Tab „Chats“. Darin sind private Chats, in denen die andere Person zuletzt geschrieben hat, ohne Bots und Archiv. Oben stehen die, die am längsten warten.",
  "en": "The list opens by long-pressing the “Chats” tab. It shows private chats where the other person wrote last, without bots and the archive. Those waiting longest are at the top.",
  "es": "La lista se abre manteniendo pulsada la pestaña «Chats». Incluye los chats privados en los que la otra persona escribió el último mensaje, sin bots ni chats archivados. Arriba están quienes llevan más tiempo esperando.",
  "fa": "فهرست با لمس طولانی روی زبانه «گفتگوها» باز می‌شود. در آن گفتگوهای خصوصی هست که آخرین پیام را طرف مقابل فرستاده، بدون ربات‌ها و بایگانی. بالای فهرست کسانی هستند که بیشتر از همه منتظرند.",
  "fr": "La liste s'ouvre par un appui long sur l'onglet « Discussions ». Elle contient les discussions privées où votre interlocuteur a écrit en dernier, sans bots ni archives. En haut, ceux qui attendent depuis le plus longtemps.",
  "id": "Daftar dibuka dengan menekan dan menahan tab “Obrolan”. Isinya obrolan pribadi yang pesan terakhirnya dari lawan bicara, tanpa bot dan arsip. Yang paling lama menunggu ada di atas.",
  "it": "L'elenco si apre tenendo premuta la scheda «Chat». Contiene le chat private in cui l'ultimo messaggio è dell'altra persona, senza bot né archivio. In alto c'è chi aspetta da più tempo.",
  "ko": "‘대화’ 탭을 길게 누르면 목록이 열립니다. 상대방이 마지막으로 메시지를 보낸 개인 대화가 표시되며, 봇과 보관함은 제외됩니다. 가장 오래 기다린 사람이 위에 표시됩니다.",
  "ms": "Senarai dibuka dengan tekan lama pada tab “Bual”. Di dalamnya ada bual peribadi yang mesej terakhirnya daripada orang lain, tanpa bot dan arkib. Yang paling lama menunggu berada di atas.",
  "nl": "De lijst open je door lang op het tabblad “Chats” te drukken. Daarin staan privéchats waarin de ander als laatste schreef, zonder bots en archief. Bovenaan staan degenen die het langst wachten.",
  "pl": "Lista otwiera się po przytrzymaniu karty „Czaty”. Są w niej czaty prywatne, w których ostatni napisał rozmówca, bez botów i archiwum. Na górze ci, którzy czekają najdłużej.",
  "pt": "A lista abre ao tocar e segurar a aba “Chats”. Nela ficam os chats privados em que a outra pessoa escreveu por último, sem bots e sem chats arquivados. No topo ficam os que esperam há mais tempo.",
  "tr": "Liste, “Sohbetler” sekmesine basılı tutunca açılır. İçinde son yazanın karşı taraf olduğu özel sohbetler bulunur, botlar ve arşiv hariç. En uzun bekleyenler üstte.",
  "uk": "Список відкривається довгим натисканням на вкладку «Чати». У ньому особисті чати, де останнім написав співрозмовник, без ботів і архіву. Угорі ті, хто чекає найдовше.",
  "uz": "Roʻyxat pastdagi “Chatlar” boʻlimini bosib turganda ochiladi. Unda oxirgi boʻlib suhbatdosh yozgan shaxsiy chatlar bor, botlar va arxivsiz. Eng uzoq kutayotganlar yuqorida."
 },
