 "Точка А есть. Долгое нажатие ставит Б": {
  "ar": "النقطة أ محددة. اضغط مطولًا لوضع ب",
  "be": "Кропка А ёсць. Доўгі націск ставіць Б",
  "ca": "Punt A posat. Manteniu premut per a posar B",
  "de": "Punkt A ist gesetzt. Lange drücken, um B zu setzen",
