 "Удалённое": {
  "ar": "المحذوفة",
  "be": "Выдаленае",
  "ca": "Missatges suprimits",
  "de": "Gelöscht",
  "en": "Deleted",
  "es": "Mensajes eliminados",
  "fa": "حذف‌شده‌ها",
  "fr": "Messages supprimés",
  "id": "Pesan dihapus",
  "it": "Messaggi eliminati",
  "ko": "삭제됨",
  "ms": "Mesej dihapus",
  "nl": "Verwijderd",
  "pl": "Usunięte",
  "pt": "Mensagens apagadas",
  "tr": "Silinen",
  "uk": "Видалене",
  "uz": "Oʻchirilgan"
 },
 "Удалённые собеседником сообщения остаются в чате с пометкой «удалено». У отредактированных в контекстном меню доступна история правок.\n\nСекретные чаты и самоуничтожающиеся сообщения не затрагиваются.": {
  "ar": "تبقى الرسائل التي حذفها الطرف الآخر في المحادثة مع علامة «محذوفة». وللرسائل المعدّلة يتوفر سجل التعديلات في القائمة السياقية.\n\nلا يشمل ذلك المحادثات السرية والرسائل ذاتية التدمير.",
  "be": "Выдаленыя суразмоўцам паведамленні застаюцца ў чаце з пазнакай «выдалена». У адрэдагаваных у кантэкстным меню даступная гісторыя правак.\n\nСакрэтныя чаты і паведамленні, якія самазнішчаюцца, не закранаюцца.",
  "ca": "Els missatges que suprimeix l'altra persona es queden al xat amb la marca «suprimit». Als missatges editats, l'historial d'edicions està disponible al menú contextual.\n\nNo afecta els xats secrets ni els missatges autodestructius.",
  "de": "Von der anderen Person gelöschte Nachrichten bleiben mit dem Vermerk „gelöscht“ im Chat. Bei bearbeiteten Nachrichten ist im Kontextmenü der Bearbeitungsverlauf verfügbar.\n\nGeheime Chats und selbstzerstörende Nachrichten sind nicht betroffen.",
  "en": "Messages deleted by the other person stay in the chat marked “deleted”. Edited messages have edit history in the context menu.\n\nSecret chats and self-destructing messages are not affected.",
  "es": "Los mensajes que elimina la otra persona se quedan en el chat con la marca «eliminado». En los mensajes editados, el historial de ediciones está disponible en el menú contextual.\n\nNo afecta a los chats secretos ni a los mensajes autodestructivos.",
  "fa": "پیام‌هایی که طرف مقابل حذف کرده با علامت «حذف‌شده» در گفتگو می‌مانند. برای پیام‌های ویرایش‌شده، تاریخچه ویرایش در منوی زمینه در دسترس است.\n\nگفتگوهای محرمانه و پیام‌های خودتخریب را شامل نمی‌شود.",
  "fr": "Les messages supprimés par votre interlocuteur restent dans la discussion avec la mention « supprimé ». Pour les messages modifiés, l'historique des modifications est disponible dans le menu contextuel.\n\nLes discussions secrètes et les messages à autodestruction ne sont pas concernés.",
  "id": "Pesan yang dihapus lawan bicara tetap ada di obrolan dengan tanda “dihapus”. Pesan yang diedit punya riwayat edit di menu konteks.\n\nSecret Chat dan pesan yang hancur otomatis tidak terpengaruh.",
  "it": "I messaggi eliminati dall'altra persona restano nella chat con l'indicazione «eliminato». Per quelli modificati, la cronologia modifiche è disponibile nel menu contestuale.\n\nLe chat segrete e i messaggi autodistruttivi non sono interessati.",
  "ko": "상대방이 삭제한 메시지는 ‘삭제됨’ 표시와 함께 대화에 남습니다. 수정된 메시지는 컨텍스트 메뉴에서 수정 기록을 볼 수 있습니다.\n\n비밀 대화와 자동 삭제 메시지에는 적용되지 않습니다.",
  "ms": "Mesej yang dihapus oleh orang lain kekal dalam bual dengan tanda “dihapus”. Mesej yang disunting ada sejarah suntingan dalam menu konteks.\n\nBual Rahsia dan mesej musnah sendiri tidak terjejas.",
  "nl": "Berichten die de ander heeft verwijderd, blijven in de chat staan met de markering “verwijderd”. Bij bewerkte berichten is de bewerkgeschiedenis beschikbaar in het contextmenu.\n\nGeheime chats en zelfvernietigende berichten vallen hier niet onder.",
  "pl": "Wiadomości usunięte przez rozmówcę zostają w czacie z oznaczeniem „usunięto”. Przy edytowanych w menu kontekstowym jest dostępna historia edycji.\n\nCzaty sekretne i wiadomości znikające nie są objęte.",
  "pt": "As mensagens apagadas pela outra pessoa ficam no chat com a marca “apagada”. As editadas têm o histórico de edições no menu de contexto.\n\nChats secretos e mensagens autodestrutivas não são afetados.",
  "tr": "Karşı tarafın sildiği mesajlar sohbette “silindi” işaretiyle kalır. Düzenlenen mesajların bağlam menüsünde düzenleme geçmişi bulunur.\n\nGizli sohbetler ve kendini imha eden mesajlar etkilenmez.",
  "uk": "Видалені співрозмовником повідомлення лишаються в чаті з позначкою «видалено». У відредагованих у контекстному меню доступна історія змін.\n\nСекретні чати й повідомлення, що самознищуються, не зачіпаються.",
  "uz": "Suhbatdosh oʻchirgan xabarlar chatda “oʻchirilgan” belgisi bilan qoladi. Tahrirlangan xabarlarning kontekst menyusida tahrirlar tarixi bor.\n\nMaxfiy chatlar va oʻz-oʻzidan oʻchadigan xabarlarga bu taʼsir qilmaydi."
 },
 "Удалённых сообщений нет. Сохраняются только те, что собеседник удалил при включённом «Сохранять удалённые», и только если телефон успел их получить.": {
  "ar": "لا توجد رسائل محذوفة. تُحفظ فقط الرسائل التي حذفها الطرف الآخر أثناء تفعيل «حفظ الرسائل المحذوفة»، وفقط إذا كان الهاتف قد استلمها.",
  "be": "Выдаленых паведамленняў няма. Захоўваюцца толькі тыя, што суразмоўца выдаліў, калі было ўключана «Захоўваць выдаленыя», і толькі калі тэлефон паспеў іх атрымаць.",
  "ca": "No hi ha missatges suprimits. Només es desen els que l'altra persona ha suprimit amb «Desa els suprimits» activat, i només si el telèfon els havia arribat a rebre.",
  "de": "Keine gelöschten Nachrichten. Gespeichert werden nur Nachrichten, die die andere Person gelöscht hat, während „Gelöschte behalten“ an war, und nur wenn das Telefon sie schon empfangen hatte.",
  "en": "No deleted messages. Only messages deleted while “Keep deleted” was on are saved, and only if the phone had received them.",
  "es": "No hay mensajes eliminados. Solo se guardan los que la otra persona eliminó con «Guardar eliminados» activado, y solo si el teléfono llegó a recibirlos.",
  "fa": "پیام حذف‌شده‌ای نیست. فقط پیام‌هایی ذخیره می‌شوند که طرف مقابل وقتی «ذخیره پیام‌های حذف‌شده» روشن بوده حذف کرده، و فقط اگر گوشی آن‌ها را دریافت کرده باشد.",
  "fr": "Aucun message supprimé. Seuls sont conservés les messages que votre interlocuteur a supprimés pendant que « Conserver les messages supprimés » était activé, et seulement si le téléphone les avait déjà reçus.",
  "id": "Tidak ada pesan yang dihapus. Yang disimpan hanya pesan yang dihapus lawan bicara saat “Simpan yang dihapus” aktif, dan hanya jika ponsel sempat menerimanya.",
  "it": "Nessun messaggio eliminato. Vengono salvati solo quelli che l'altra persona ha eliminato con «Salva eliminati» attivo, e solo se il telefono ha fatto in tempo a riceverli.",
  "ko": "삭제된 메시지가 없습니다. ‘삭제된 메시지 보관’이 켜져 있을 때 상대방이 삭제한 메시지만, 그리고 휴대폰이 이미 받은 경우에만 저장됩니다.",
  "ms": "Tiada mesej yang dihapus. Yang disimpan hanya mesej yang dihapus oleh orang lain semasa “Simpan yang dihapus” dihidupkan, dan hanya jika telefon sempat menerimanya.",
  "nl": "Geen verwijderde berichten. Alleen berichten die de ander heeft verwijderd terwijl “Verwijderde bewaren” aan stond, worden bewaard, en alleen als de telefoon ze al had ontvangen.",
  "pl": "Brak usuniętych wiadomości. Zapisywane są tylko te, które rozmówca usunął przy włączonym „Zapisuj usunięte”, i tylko jeśli telefon zdążył je odebrać.",
  "pt": "Não há mensagens apagadas. Só são salvas as que a outra pessoa apagou com “Manter apagadas” ativado, e só se o celular tiver chegado a recebê-las.",
  "tr": "Silinmiş mesaj yok. Yalnızca “Silinenleri sakla” açıkken karşı tarafın sildiği ve telefonun almaya yetiştiği mesajlar kaydedilir.",
  "uk": "Видалених повідомлень немає. Зберігаються лише ті, що співрозмовник видалив, коли було ввімкнено «Зберігати видалені», і лише якщо телефон устиг їх отримати.",
  "uz": "Oʻchirilgan xabarlar yoʻq. Faqat “Oʻchirilganlarni saqlash” yoqilganida suhbatdosh oʻchirgan va telefon qabul qilib ulgurgan xabarlar saqlanadi."
 },
