 "Чатов с этой меткой нет. Метка ставится долгим нажатием на чат, пункт «Метки».": {
  "ar": "لا محادثات بهذا الوسم. يُضاف الوسم بالضغط المطوّل على محادثة واختيار «الوسوم».",
  "be": "Чатаў з гэтай меткай няма. Метка ставіцца доўгім націскам на чат, пункт «Меткі».",
  "ca": "No hi ha xats amb aquesta etiqueta. Per a posar-la, manteniu premut un xat i trieu «Etiquetes».",
  "de": "Keine Chats mit diesem Label. Ein Label setzt du durch langes Drücken auf den Chat, Punkt „Labels“.",
  "en": "No chats with this label. To add it, long-press a chat and choose “Labels”.",
  "es": "No hay chats con esta etiqueta. Para ponerla, mantén pulsado un chat y elige «Etiquetas».",
  "fa": "گفتگویی با این برچسب نیست. برچسب با لمس طولانی روی گفتگو و گزینه «برچسب‌ها» گذاشته می‌شود.",
  "fr": "Aucune discussion avec cette étiquette. Pour l'ajouter, faites un appui long sur une discussion, option « Étiquettes ».",
  "id": "Tidak ada obrolan dengan label ini. Label dipasang dengan menekan dan menahan obrolan, pilih “Label”.",
  "it": "Nessuna chat con questa etichetta. Per aggiungerla, tieni premuta una chat e scegli «Etichette».",
  "ko": "이 라벨이 붙은 대화가 없습니다. 대화를 길게 누르고 ‘라벨’을 선택하면 라벨을 붙일 수 있습니다.",
  "ms": "Tiada bual dengan label ini. Label dipasang dengan tekan lama pada bual, pilih “Label”.",
  "nl": "Geen chats met dit label. Een label zet je door lang op de chat te drukken, onderdeel “Labels”.",
  "pl": "Nie ma czatów z tą etykietą. Etykietę dodaje się przez przytrzymanie czatu, pozycja „Etykiety”.",
  "pt": "Não há chats com esta etiqueta. Para colocá-la, toque e segure um chat e escolha “Etiquetas”.",
  "tr": "Bu etikete sahip sohbet yok. Etiket, sohbete basılı tutup “Etiketler” seçeneğiyle eklenir.",
  "uk": "Чатів із цією міткою немає. Мітка ставиться довгим натисканням на чат, пункт «Мітки».",
  "uz": "Bu yorliqli chatlar yoʻq. Yorliq chatni bosib turib, “Yorliqlar” bandi orqali qoʻyiladi."
 },
